			["ErrInit"] = "Inițializare eșuată", ["ErrMbrTooBig"] = "Imaginea are mai mult decât cei circa 2 TB pe care îi poate adresa o schemă MBR, așa că nu poate fi restaurată pe această unitate. Nu s-a schimbat nimic - unitatea nu a fost formatată.", ["ErrImageBadCheck"] = "Imaginea de rezervă nu a trecut verificarea de integritate, deci poate fi coruptă sau incompletă. Unitatea destinație NU a fost formatată.", ["ErrImageNoWindows"] = "Imaginea nu conține o instalare de Windows (nu există registrul SYSTEM pe partiția ei Windows). Nu s-a scris nimic pe destinație.", ["ErrFfuExtension"] = "Restaurarea unei clone complete are nevoie de un fișier clonă cu extensia .ffu.", ["ErrNoDiskInfo"] = "Windows nu a returnat nicio informație despre discuri. Get-Disk poate lipsi (o versiune WinPE fără componenta StorageWMI) sau serviciul Virtual Disk poate să nu ruleze.", ["ErrIsoMountFailed"] = "Windows nu a putut monta fișierul ISO. Poate fi deteriorat, sau încă folosit de alt program.", ["ErrNoInstallImage"] = "Acest ISO nu are nici sources\\install.wim, nici sources\\install.esd, deci nu este o imagine de instalare Windows.", ["ErrNoDriveLetters"] = "Nu mai sunt litere de unitate libere. Deconectează sau demontează o unitate și încearcă din nou.", ["ErrDownloadIncomplete"] = "Descărcarea s-a oprit prea devreme: au ajuns {0} din {1}. Fișierul nu a fost salvat.", ["ErrRawEngineMft"] = "Tabela principală de fișiere a acestui volum e împărțită într-o listă de atribute suplimentară, pe care motorul brut nu o citește - ar lăsa fișiere pe dinafară fără să spună. Oprește motorul brut și folosește motorul standard pentru acest volum.", ["ErrRawEngineNotNtfs"] = "Volumul instantaneu nu e NTFS, iar motorul brut clonează doar volume Windows NTFS. Oprește motorul brut pentru acest volum.", ["ErrBootSector"] = "Sectorul de boot {0} nu a putut fi citit, așa că acest sistem de fișiere nu poate fi examinat.", ["ErrSessionBad"] = "Acest fișier de sesiune e gol sau nu e o sesiune de scanare DriveForge.", ["ErrSessionNewer"] = "Această sesiune de scanare a fost salvată de un DriveForge mai nou (format v{0}). Actualizează DriveForge ca să o deschizi.", ["ErrWrongDiskRecover"] = "Unitatea {0}: nu e cea de pe care s-a făcut scanarea acestei sesiuni - litera ei arată acum spre alt disc. Recuperarea a fost oprită ca să nu se citească datele greșite. Reconectează unitatea originală, sau scanează din nou.", ["ErrWrongDiskDeep"] = "Unitatea {0}: nu e cea pe care a pornit această scanare profundă - litera ei arată acum spre alt disc. Reluarea a fost oprită ca să nu fie scanată unitatea greșită.", ["ErrUnsupportedVolume"] = "Această sursă nu e un sistem de fișiere din care DriveForge poate recupera. Citește NTFS, exFAT, FAT32, FAT16 și FAT12.", ["ErrBackupNotCreated"] = "Fișierul imagine de rezervă nu a fost creat.", ["ErrFfuNoPartitions"] = "Restaurarea s-a terminat, dar discul destinație nu are nicio partiție, deci imaginea poate fi nevalidă sau scrierea poate să fi eșuat.", ["ErrOpenDiskWrite"] = "Nu s-a putut deschide discul pentru scriere (eroare Windows {0}). Închide orice program care folosește unitatea, asigură-te că DriveForge rulează ca administrator, și încearcă din nou.",
