			["BzStartOp"] = "Iniciando la operación de disco...",
			["StHealthDone"] = "Informe de estado completado.",
			["StPaused"] = "Operación en pausa.",
			["ErrLogsFolder"] = "No se pudo abrir la carpeta de registros",
			["ErrMultiBoot"] = "Error en la configuración multiarranque",
