"RecoverSaveSessionButton"] = "Guardar sesión…", ["RecoverOpenSessionButton"] = "Abrir sesión…", ["RecoverZipTitle"] = "Recuperar los archivos seleccionados en un zip", ["SessionSaveTitle"] = "Guardar sesión de escaneo", ["SessionOpenTitle"] = "Abrir sesión de escaneo", ["SessionNothing"] = "Ejecuta primero un escaneo.", ["SessionSaved"] = "Sesión guardada — {0} archivos.", ["SessionLoaded"] = "Sesión cargada — {0} archivos de {1}.", ["PreviewSelect"] = "Selecciona una imagen o un archivo de texto para previsualizar.", ["PreviewNone"] = "Sin vista previa para este tipo de archivo.", ["PreviewFail"] = "No se pudo previsualizar (dañado, truncado o no compatible).", ["A11yHelp"] = "Ayuda", ["A11ySearch"] = "Filtrar archivos", ["A11yTypeFilter"] = "Filtrar por tipo de archivo", ["A11yTreemap"] = "Mapa de tamaño de carpetas", ["LiveCompleted"] = "Completado 100%", ["LiveStopped"] = "Detenido", ["LiveSpeedTest"] = "Prueba de velocidad", ["LivePercent"] = "Prueba de velocidad {0}%", ["DescIsoWrite"] = "Elige cualquier ISO de arranque (Linux, BSD, herramientas de rescate, etc.). DriveForge lo escribe en el USB como imagen de disco sin procesar, haciéndolo arrancable en BIOS + UEFI.", ["Step2IsoImage"] = "Imagen ISO", ["Step2ImageFile"] = "Archivo de imagen", ["TbPartition"] = "Partición", ["MvPartOption"] = "Mover una partición", ["ToolGrpDiagnose"] = "Diagnóstico", ["ToolGrpMaintain"] = "Mantenimiento", ["ToolGrpErase"] = "Borrado", ["MvGptVerifyFail"] = "DriveForge no pudo verificar las sumas de comprobación GPT de este disco, así que no arriesgará un movimiento — no se cambió nada. (El GPT puede estar dañado o el disco usa un diseño inusual.)", ["MvTitle"] = "Mover una partición", ["MvNoParts"] = "No se encontraron particiones en el MBR de este disco.", ["MvPickPart"] = "¿Qué partición quieres mover?", ["MvDirPrompt"] = "¿Mover la partición hacia el inicio o el final del disco?", ["MvLeft"] = "Hacia el inicio del disco", ["MvRight"] = "Hacia el final del disco", ["MvAmountPrompt"] = "¿Cuántos MB se debe mover la partición?", ["MvOutOfRange"] = "Ese movimiento se saldría del borde del disco o antes del primer 1 MB. Elige una cantidad menor.", ["MvOverlap"] = "Ese movimiento se solaparía con otra partición. Elige una cantidad menor o la otra dirección.", ["MvConfirm"] = "¿Mover la partición #{0} ({1})?\n\n    Desde el desplazamiento {2}\n    Al desplazamiento {3}\n\n⚠ EXPERIMENTAL. Los datos de la partición se reubican físicamente y se reescribe la tabla de particiones.\n\n• Crea primero una imagen del disco (Recuperar → Crear imagen de disco) por si acaso.\n• NO apagues ni desconectes durante el movimiento — no se puede interrumpir de forma segura.\n\n¿Continuar?", ["MvWorking"] = "Moviendo la partición — NO apagues…", ["MvDone"] = "Listo. La partición #{0} fue movida. Si falta una letra de unidad, revisa Administración de discos.", ["MvStopIgnored"] = "Pulsaste Detener y no se obedeció a propósito: un movimiento de partición no se puede interrumpir con seguridad; a medio camino la partición existe en dos sitios y no se puede leer en ninguno. Se dejó terminar. No se dañó nada.", ["MvFailed"] = "No se pudo mover la partición. La tabla de particiones quedó sin cambios.", ["PtResize"] = "Redimensionar una partición (ampliar / reducir)", ["PtCreate"] = "Crear una partición (en el espacio libre)", ["PtCreatePrompt"] = "¿Tamaño de la nueva partición en MB? (vacío = todo el espacio sin asignar)", ["PtCreateConfirm"] = "¿Crear una nueva partición en el Disco {0} usando su espacio sin asignar?\n\nLas particiones existentes no se tocan.", ["PtCreateDone"] = "Listo. Se creó una nueva partición en el Disco {0}.", ["PtCreateFailed"] = "No se pudo crear una partición — puede que no haya espacio sin asignar en el disco. Consulta los detalles abajo.", ["PtDeleteFailed"] = "El volumen {0}: no se eliminó: Windows lo rechazó. Puede estar en uso o ser una partición de sistema o de recuperación protegida. Mira los detalles más abajo.", ["PtDelete"] = "Eliminar una partición (liberar su espacio)", ["PtDeleteConfirm"] = "¿Eliminar el volumen {0}: y convertirlo en espacio sin asignar?\n\n⚠ Todo lo de {0}: se borrará permanentemente. No se puede deshacer.", ["PtDeleteDone"] = "Listo. El volumen {0}: fue eliminado; su espacio ahora está sin asignar.", ["PtResizePrompt"] = "¿Redimensionar el volumen {0}: — ampliar o reducir?", ["PtGrow"] = "Ampliar (extender al espacio libre que le sigue)", ["PtShrink"] = "Reducir (liberar espacio al final)", ["PtShrinkPrompt"] = "¿Cuántos MB liberar de {0}: ? (máx ≈ {1} MB)", ["PtGrowPrompt"] = "¿Cuántos MB añadir a {0}: ? (vacío = todo el espacio libre justo después)", ["PtBadAmount"] = "Introduce un número entero de megabytes.", ["PtShrinkConfirm"] = "¿Reducir {0}: en {1} MB?\n\nEl espacio liberado queda sin asignar. Tus archivos se conservan.", ["PtGrowConfirm"] = "¿Ampliar {0}: al espacio sin asignar que le sigue?", ["PtResizeWorking"] = "Redimensionando {0}: …", ["PtResizeDone"] = "Listo. El volumen {0}: fue redimensionado.", ["PtResizeFailed"] = "diskpart no pudo redimensionar el volumen — consulta los detalles abajo (p. ej. no hay espacio libre justo después, o limitado por archivos inamovibles).", ["PtNoDisk"] = "Selecciona primero un disco (Unidad a probar).", ["PtSystemBlocked"] = "Es un disco del sistema — DriveForge no modifica sus particiones.", ["PtTitle"] = "Herramientas de partición", ["PtPrompt"] = "Elige una acción para el Disco {0}:", ["PtQuickPart"] = "Partición rápida (borrar y recrear)", ["PtInit"] = "Inicializar un disco vacío / RAW", ["PtConvert"] = "Convertir MBR ↔ GPT (borra el disco)", ["PtCheck"] = "Comprobar sistema de archivos (CHKDSK)", ["PtActive"] = "Marcar la primera partición como activa (arranque MBR)", ["PtFindLost"] = "Buscar particiones perdidas (análisis de solo lectura)", ["PtConfirmBody"] = "¿{0} en este disco?\n\n    Disco {1} — {2} — {3}\n\nActualmente contiene:\n{4}\n\n⚠ Todo será BORRADO. No se puede deshacer.", ["PtWorking"] = "{0} en el disco seleccionado…", ["PtCountPrompt"] = "¿Cuántas particiones crear en el Disco {0}?", ["PtFsPrompt"] = "Elige el sistema de archivos para las nuevas particiones:", ["PtQuickDone"] = "Listo. El Disco {0} tiene ahora {1} × {2} partición(es).", ["PtInitPrompt"] = "¿Con qué estilo de partición inicializar el Disco {0}?", ["PtGpt"] = "GPT (moderno, >2 TB, UEFI)", ["PtMbr"] = "MBR (antiguo, BIOS)", ["PtInitDone"] = "Listo. El Disco {0} fue inicializado y formateado (NTFS).", ["PtConvertDone"] = "Listo. El Disco {0} ahora es {1}.", ["PtNoVolumes"] = "Este disco no tiene volúmenes formateados.",["PtGrowNoRoom"] = "{0}: no puede crecer: no hay espacio sin asignar inmediatamente después.\n\nUna partición solo puede crecer hacia el espacio libre que la sigue directamente en el disco. El espacio anterior, o el que hay tras otra partición, no sirve: elimina o mueve antes lo que haya en medio.", ["PtPickVolume"] = "¿Qué volumen quieres comprobar?", ["PtChecking"] = "Comprobando {0}: …", ["PtCheckDone"] = "Comprobación de {0}: finalizada.", ["PtActiveGpt"] = "En un disco GPT no existe la marca 'activa' — UEFI arranca desde la partición de sistema EFI.", ["PtActiveConfirm"] = "¿Marcar la primera partición del Disco {0} como activa (arrancable)?", ["PtActiveDone"] = "Listo. La primera partición del Disco {0} ya está activa.", ["PtActiveNotSet"] = "Disco {0}: la primera partición sigue sin estar marcada como activa. diskpart no informó de ningún error, pero el indicador no cambió: puede que el disco no tenga una partición 1, o que Windows lo haya rechazado. Mira los detalles más abajo.", ["PtQuickPartial"] = "El disco {0} no quedó como se pidió: tiene {1} partición(es) de las {2} solicitadas, y Windows informa de estos sistemas de archivos en él: {3}. diskpart se detuvo a medio camino sin informar de ningún error. Mira los detalles más abajo.", ["MbFormatNoFs"] = "El disco {0} se particionó, pero Windows no informa de un sistema de archivos {1} en él: el formateo no se completó, aunque diskpart no informó de ningún error. La unidad todavía no está lista para usar. Mira los detalles más abajo y vuelve a intentarlo, o formatéala desde Administración de discos.", ["PtScanningLost"] = "Analizando el Disco {0} en busca de particiones perdidas…", ["PtLostNone"] = "No se encontraron firmas de partición en el Disco {0}.", ["PtLostUnmounted"] = "no montada (posiblemente perdida)", ["PtLostFound"] = "Encontradas {0} partición(es) en el Disco {1}:", ["PtLostHint"] = "Análisis de solo lectura — no se modificó nada. Para recuperar una partición perdida, usa una herramienta de terceros dedicada a la recuperación de particiones; para rescatar sus archivos, crea una imagen del disco y recupéralos desde la imagen.",["PtLostStopped"] = "\n\nEl análisis no terminó, así que esto es solo lo que alcanzó a encontrar: el resto del disco no se examinó.", ["WipeSsd"] = "Borrado SSD (TRIM — el borrado adecuado para SSD)", ["SsdConfirm"] = "¿Borrado SSD del Disco {0}?\n\n    {1} — {2}\n\nActualmente contiene:\n{3}\n\n⚠ Todos los datos se descartarán. No se puede deshacer.", ["SsdWorking"] = "Borrando el Disco {0} (formato rápido + TRIM)…", ["SsdDone"] = "Listo. El Disco {0} fue limpiado y borrado con TRIM — en un SSD el controlador descarta los bloques de datos antiguos. Para una sanitización certificada, ejecuta también la herramienta Secure Erase del fabricante.", ["RecPreviewLabel"] = "Vista previa", ["EjectDriveButton"] = "Quitar con seguridad", ["AddAllDriversCheck"] = "Añadir TODOS los controladores de este PC (más lento)", ["AddNetworkDriversCheck"] = "Añadir los controladores de red / Wi-Fi de este PC", ["EjectWhenDoneCheck"] = "Expulsar la unidad al terminar", ["UseDismEngineCheck"] = "Usar el motor de Microsoft (DISM)", ["UseNtfsRawEngineCheck"] = "Clonación rápida", ["OpenReportButton"] = "Abrir último informe", ["ScheduleCloneButton"] = "Programar esta clonación (copia automática)…", ["StartBackup"] = "Copia de seguridad en archivo de imagen", ["SbCleanT"] = "Limpiar rastros", ["SbCleanS"] = "Libera espacio y borra rastros de uso", ["CleanPanelTitle"] = "Limpiar rastros", ["CleanPanelDesc"] = "Recupera espacio en disco y elimina los rastros de uso que dejan Windows y tus aplicaciones. Marca lo que quieras borrar, pulsa Analizar para ver cuánto liberarás y luego Limpiar ahora. Nada sale nunca de tu PC.", ["ChkCleanTemp"] = "Archivos temporales (Windows + apps)", ["ChkCleanRecent"] = "Archivos recientes y jump lists", ["ChkCleanThumbs"] = "Caché de miniaturas", ["ChkCleanBrowser"] = "Cachés de navegador (Edge, Chrome, Firefox)", ["ChkCleanPrefetch"] = "Prefetch de Windows", ["ChkCleanUpdate"] = "Caché de Windows Update", ["ChkCleanRecycle"] = "Papelera de reciclaje (todas las unidades)", ["ChkCleanDns"] = "Caché de resolución DNS", ["ChkCleanClipboard"] = "Contenido del portapapeles", ["CleanAnalyzeButton"] = "Analizar", ["CleanRunButton"] = "Limpiar ahora", ["CleanSelectAllButton"] = "Seleccionar todo", ["CleanNote"] = "Seguro por diseño: solo se borran las ubicaciones estándar de caché y temporales, y se omiten los archivos en uso. Vaciar la Papelera elimina su contenido de forma permanente. Algunos elementos (Prefetch, caché de Windows Update) requieren permisos de administrador.", ["CleanAnalyzing"] = "Analizando…", ["CleanAnalyzeResult"] = "Se pueden liberar unos {0}.", ["CleanAnalyzeAdvanced"] = "Hay otros {0} en los elementos avanzados: marca [[CleanAdvancedToggle]] para incluirlos.", ["BzCleaning"] = "Limpiando...", ["CleanNothingSelected"] = "Nada seleccionado.", ["CleanConfirmTitle"] = "Limpiar rastros", ["CleanConfirmBody"] = "Esto eliminará permanentemente los elementos seleccionados:", ["CleanCleaningX"] = "Limpiando: {0}…", ["CleanDone"] = "Listo — liberado {0} ({1} archivos eliminados).", ["CleanStopped"] = "Detenido: se liberaron {0} ({1} archivos eliminados). {2} de los elementos marcados no se limpiaron.", ["RecTypeAll"] = "Todos", ["RecTypePictures"] = "Imágenes", ["RecTypeDocuments"] = "Documentos", [