			["RecFilterLabel"] = "Filtern", ["RecSelectAllButton"] = "Alle auswählen", ["RecSelectNoneButton"] = "Auswahl aufheben", ["RecoverStopButton"] = "Stopp", ["RecoverDeepScanButton"] = "Tiefenscan", ["CreateImageButton"] = "Datenträgerabbild erstellen…", ["OpenImageButton"] = "Abbild öffnen…", ["CleanTab1Header"] = "Spuren bereinigen", ["CleanTab2Header"] = "Speicherplatz", ["AnalyzePanelDesc"] = "Finden Sie heraus, was Ihren Datenträger füllt: Scannen Sie einen beliebigen Ordner oder Datenträger, sehen Sie eine Größenkarte der Unterordner, die größten Dateien und doppelte Kopien, die Sie gefahrlos löschen können. Schreibgeschützt, bis Sie löschen.", ["AnalyzeFolderLabel"] = "Zu scannender Ordner", ["AnalyzeBrowseButton"] = "Durchsuchen…", ["AnalyzeScanButton"] = "Scannen", ["AnalyzeStopButton"] = "Stopp", ["AnalyzeBigFilesTab"] = "Größte Dateien", ["AnalyzeDupesTab"] = "Doppelte Dateien", ["AnalyzeKeepFirstButton"] = "Duplikate auswählen (1 behalten)", ["AnalyzeDeleteButton"] = "Auswahl löschen", ["AnalyzeNoFolder"] = "Wählen Sie zuerst einen Ordner zum Scannen.", ["AnalyzeScanning"] = "Scannen… {0}", ["AnalyzeHashing"] = "Suche nach Duplikaten…", ["AnalyzeResult"] = "{0:N0} Dateien · {1} gesamt · größter Unterordner: {2}", ["AnalyzeDupResult"] = "· {0} Duplikatgruppen ({1} zusätzliche Kopien, {2} freigebbar)", ["AnalyzeDeleteTitle"] = "Dateien löschen", ["AnalyzeDeleteDone"] = "{0} Datei(en) entfernt — {1}. Was in den Papierkorb gewandert ist, gibt erst Speicher frei, wenn Sie ihn leeren.", ["PredReplace"] = "Bald ersetzen", ["PredWatch"] = "Dieses Laufwerk beobachten", ["PredHealthy"] = "Keine Ausfallzeichen", ["PredUnknown"] = "Nicht genügend SMART-Daten für Vorhersage", ["PredReasonHealth"] = "meldet {0}", ["PredReasonUncorrected"] = "{0} Lese- / {1} Schreibfehler nicht korrigierbar", ["PredReasonWear"] = "{0}% Abnutzung", ["PredReasonErrors"] = "{0} protokollierte Fehler", ["PredReasonTemp"] = "läuft heiß ({0} °C)", ["RecoverZipButton"] = "In ZIP wiederherstellen…", ["RecoverSaveSessionButton"] = "Sitzung speichern…", ["RecoverOpenSessionButton"] = "Sitzung öffnen…", ["RecoverZipTitle"] = "Ausgewählte Dateien in ein Zip wiederherstellen", ["SessionSaveTitle"] = "Scan-Sitzung speichern", ["SessionOpenTitle"] = "Scan-Sitzung öffnen", ["SessionNothing"] = "Führen Sie zuerst einen Scan aus.", ["SessionSaved"] = "Sitzung gespeichert — {0} Dateien.", ["SessionLoaded"] = "Sitzung geladen — {0} Dateien aus {1}.", ["PreviewSelect"] = "Wählen Sie ein Bild oder eine Textdatei für die Vorschau.", ["PreviewNone"] = "Keine Vorschau für diesen Dateityp.", ["PreviewFail"] = "Vorschau nicht möglich (beschädigt, abgeschnitten oder nicht unterstützt).", ["A11yHelp"] = "Hilfe", ["A11ySearch"] = "Dateien filtern", ["A11yTypeFilter"] = "Nach Dateityp filtern", ["A11yTreemap"] = "Ordnergrößenkarte", ["LiveCompleted"] = "100% abgeschlossen", ["LiveStopped"] = "Gestoppt", ["LiveSpeedTest"] = "Geschwindigkeitstest", ["LivePercent"] = "Geschwindigkeitstest {0}%", ["DescIsoWrite"] = "Wählen Sie ein beliebiges bootfähiges ISO (Linux, BSD, Rettungstools usw.). DriveForge schreibt es als rohes Datenträgerabbild auf den USB-Stick und macht ihn auf BIOS + UEFI bootfähig.", ["Step2IsoImage"] = "ISO-Abbild", ["Step2ImageFile"] = "Abbilddatei", ["TbPartition"] = "Partition", ["MvPartOption"] = "Partition verschieben", ["ToolGrpDiagnose"] = "Diagnose", ["ToolGrpMaintain"] = "Wartung", ["ToolGrpErase"] = "Löschen", ["MvGptVerifyFail"] = "DriveForge konnte die GPT-Prüfsummen dieses Datenträgers nicht verifizieren und riskiert daher keine Verschiebung — es wurde nichts geändert. (Die GPT ist möglicherweise beschädigt, oder der Datenträger hat ein ungewöhnliches Layout.)", ["MvTitle"] = "Partition verschieben", ["MvNoParts"] = "Im MBR dieses Datenträgers wurden keine Partitionen gefunden.", ["MvPickPart"] = "Welche Partition möchten Sie verschieben?", ["MvDirPrompt"] = "Partition zum Anfang oder zum Ende des Datenträgers verschieben?", ["MvLeft"] = "Zum Anfang des Datenträgers", ["MvRight"] = "Zum Ende des Datenträgers", ["MvAmountPrompt"] = "Um wie viele MB soll die Partition verschoben werden?", ["MvOutOfRange"] = "Diese Verschiebung würde über den Rand des Datenträgers oder vor das erste 1 MB hinausgehen. Wählen Sie einen kleineren Wert.", ["MvOverlap"] = "Diese Verschiebung würde eine andere Partition überlappen. Wählen Sie einen kleineren Wert oder die andere Richtung.", ["MvConfirm"] = "Partition #{0} ({1}) verschieben?\n\n    Von Offset {2}\n    Zu Offset {3}\n\n⚠ EXPERIMENTELL. Die Daten der Partition werden physisch verschoben und die Partitionstabelle neu geschrieben.\n\n• Erstellen Sie zuerst ein Abbild des Datenträgers (Wiederherstellen → Datenträgerabbild erstellen).\n• Schalten Sie während des Verschiebens NICHT aus und trennen Sie nicht — es kann nicht sicher unterbrochen werden.\n\nFortfahren?", ["MvWorking"] = "Partition wird verschoben — NICHT ausschalten…", ["MvDone"] = "Fertig. Partition #{0} wurde verschoben. Fehlt ein Laufwerkbuchstabe, prüfen Sie die Datenträgerverwaltung.", ["MvStopIgnored"] = "Sie haben Stopp gedrückt, und das wurde bewusst nicht befolgt: Eine Partitionsverschiebung lässt sich nicht gefahrlos unterbrechen — auf halbem Weg liegt die Partition an zwei Stellen und ist an keiner lesbar. Sie durfte zu Ende laufen. Es wurde nichts beschädigt.", ["MvFailed"] = "Die Partition konnte nicht verschoben werden. Die Partitionstabelle blieb unverändert.", ["PtResize"] = "Partition vergrößern / verkleinern", ["PtCreate"] = "Partition erstellen (im freien Speicher)", ["PtCreatePrompt"] = "Größe der neuen Partition in MB? (leer = der gesamte nicht zugeordnete Speicher)", ["PtCreateConfirm"] = "Eine neue Partition auf Datenträger {0} im nicht zugeordneten Speicher erstellen?\n\nVorhandene Partitionen bleiben unberührt.", ["PtCreateDone"] = "Fertig. Auf Datenträger {0} wurde eine neue Partition erstellt.", ["PtCreateFailed"] = "Partition konnte nicht erstellt werden — möglicherweise kein nicht zugeordneter Speicher vorhanden. Siehe Details unten.", ["PtDeleteFailed"] = "Das Volume {0}: wurde nicht gelöscht — Windows hat es abgelehnt. Es ist möglicherweise in Benutzung oder eine geschützte System- oder Wiederherstellungspartition. Details siehe unten.", ["PtDelete"] = "Partition löschen (Speicher freigeben)", ["PtDeleteConfirm"] = "Volume {0}: löschen und in nicht zugeordneten Speicher umwandeln?\n\n⚠ Alles auf {0}: wird dauerhaft gelöscht. Nicht rückgängig zu machen.", ["PtDeleteDone"] = "Fertig. Volume {0}: wurde gelöscht; sein Speicher ist jetzt nicht zugeordnet.", ["PtResizePrompt"] = "Volume {0}: vergrößern oder verkleinern?", ["PtGrow"] = "Vergrößern (in den freien Speicher dahinter erweitern)", ["PtShrink"] = "Verkleinern (am Ende Speicher freigeben)", ["PtShrinkPrompt"] = "Wie viele MB von {0}: freigeben? (max ≈ {1} MB)", ["PtGrowPrompt"] = "Wie viele MB zu {0}: hinzufügen? (leer = der gesamte freie Speicher direkt dahinter)", ["PtBadAmount"] = "Geben Sie eine ganze Zahl an Megabyte ein.", ["PtShrinkConfirm"] = "{0}: um {1} MB verkleinern?\n\nDer freigegebene Speicher wird nicht zugeordnet. Ihre Dateien bleiben erhalten.", ["PtGrowConfirm"] = "{0}: in den nachfolgenden, nicht zugeordneten Speicher erweitern?", ["PtResizeWorking"] = "{0}: wird in der Größe geändert…", ["PtResizeDone"] = "Fertig. Volume {0}: wurde in der Größe geändert.", ["PtResizeFailed"] = "diskpart konnte das Volume nicht ändern — siehe Details unten (z. B. kein freier Speicher direkt dahinter oder durch nicht verschiebbare Dateien begrenzt).", ["PtNoDisk"] = "Wählen Sie zuerst einen Datenträger (Laufwerk zum Testen).", ["PtSystemBlocked"] = "Das ist ein Systemdatenträger — DriveForge ändert seine Partitionen nicht.", ["PtTitle"] = "Partitionswerkzeuge", ["PtPrompt"] = "Wählen Sie eine Aktion für Datenträger {0}:", ["PtQuickPart"] = "Schnellpartitionierung (löschen & neu erstellen)", ["PtInit"] = "Leeren / RAW-Datenträger initialisieren", ["PtConvert"] = "MBR ↔ GPT konvertieren (löscht den Datenträger)", ["PtCheck"] = "Dateisystem prüfen (CHKDSK)", ["PtActive"] = "Erste Partition aktiv setzen (MBR-Boot-Flag)", ["PtFindLost"] = "Verlorene Partitionen suchen (schreibgeschützter Scan)", ["PtConfirmBody"] = "{0} auf diesem Datenträger?\n\n    Datenträger {1} — {2} — {3}\n\nEnthält derzeit:\n{4}\n\n⚠ Alles wird GELÖSCHT. Nicht rückgängig zu machen.", ["PtWorking"] = "{0} auf dem gewählten Datenträger…", ["PtCountPrompt"] = "Wie viele Partitionen auf Datenträger {0} erstellen?", ["PtFsPrompt"] = "Wählen Sie das Dateisystem der neuen Partitionen:", ["PtQuickDone"] = "Fertig. Datenträger {0} hat jetzt {1} × {2} Partition(en).", ["PtInitPrompt"] = "Datenträger {0} mit welchem Partitionsstil initialisieren?", ["PtGpt"] = "GPT (modern, >2 TB, UEFI)", ["PtMbr"] = "MBR (älter, BIOS)", ["PtInitDone"] = "Fertig. Datenträger {0} wurde initialisiert und formatiert (NTFS).", ["PtConvertDone"] = "Fertig. Datenträger {0} ist jetzt {1}.", ["PtNoVolumes"] = "Dieser Datenträger hat keine formatierten Volumes.",["PtGrowNoRoom"] = "{0}: kann nicht wachsen — unmittelbar danach gibt es keinen nicht zugeordneten Speicher.\n\nEine Partition kann nur in freien Speicher wachsen, der ihr auf dem Datenträger direkt folgt. Platz davor oder hinter einer anderen Partition lässt sich nicht nutzen: Löschen oder verschieben Sie zuerst, was dazwischen liegt.", ["PtPickVolume"] = "Welches Volume möchten Sie prüfen?", ["PtChecking"] = "Prüfe {0}: …", ["PtCheckDone"] = "Prüfung von {0}: abgeschlossen.", ["PtActiveGpt"] = "Auf einem GPT-Datenträger gibt es kein 'Aktiv'-Flag — UEFI startet von der EFI-Systempartition.", ["PtActiveConfirm"] = "Die erste Partition von Datenträger {0} als aktiv (bootfähig) setzen?", ["PtActiveDone"] = "Fertig. Die erste Partition von Datenträger {0} ist jetzt aktiv.", ["PtActiveNotSet"] = "Datenträger {0}: Die erste Partition ist weiterhin nicht als aktiv markiert. diskpart meldete keinen Fehler, aber das Flag hat sich nicht geändert — der Datenträger hat möglicherweise keine Partition 1, oder Windows hat es abgelehnt. Details siehe unten.", ["PtQuickPartial"] = "Datenträger {0} ist nicht wie gewünscht: Er hat {1} von {2} angeforderten Partitionen, und Windows meldet darauf diese Dateisysteme: {3}. diskpart hat auf halbem Weg aufgehört, ohne einen Fehler zu melden. Details siehe unten.", ["MbFormatNoFs"] = "Datenträger {0} wurde partitioniert, aber Windows meldet darauf kein {1}-Dateisystem — die Formatierung wurde nicht abgeschlossen, obwohl diskpart keinen Fehler gemeldet hat. Das Laufwerk ist noch nicht einsatzbereit. Details siehe unten; versuchen Sie es erneut oder formatieren Sie es in der Datenträgerverwaltung.", ["PtScanningLost"] = "Datenträger {0} wird nach verlorenen Partitionen durchsucht…", ["PtLostNone"] = "Auf Datenträger {0} wurden keine Partitionssignaturen gefunden.", ["PtLostUnmounted"] = "nicht eingebunden (möglicherweise verloren)", ["PtLostFound"] = "{0} Partition(en) auf Datenträger {1} gefunden:", ["PtLostHint"] = "Schreibgeschützter Scan – es wurde nichts verändert. Um eine verlorene Partition wiederherzustellen, verwende ein spezialisiertes Drittanbieter-Tool zur Partitionswiederherstellung; um ihre Dateien zu retten, erstelle ein Abbild der Festplatte und stelle aus dem Abbild wieder her.",["PtLostStopped"] = "\n\nDie Suche wurde nicht abgeschlossen - dies ist nur, was sie bis dahin erreicht hatte; der Rest des Datenträgers wurde nicht durchsucht.", ["WipeSsd"] = "SSD-Löschung (TRIM — die für SSDs passende Löschung)", ["SsdConfirm"] = "SSD-Löschung von Datenträger {0}?\n\n    {1} — {2}\n\nEnthält derzeit:\n{3}\n\n⚠ Alle Daten werden verworfen. Nicht rückgängig zu machen.", ["SsdWorking"] = "Datenträger {0} wird gelöscht (Schnellformatierung + TRIM)…", ["SsdDone"] = "Fertig. Datenträger {0} wurde bereinigt und per TRIM gelöscht — bei einer SSD verwirft der Controller die alten Datenblöcke. Für zertifizierte Bereinigung nutzen Sie zusätzlich das Secure-Erase-Tool des Herstellers.", ["RecPreviewLabel"] = "Vorschau", ["EjectDriveButton"] = "Sicher entfernen", ["AddAllDriversCheck"] = "ALLE Treiber dieses PCs hinzufügen (langsamer)", ["AddNetworkDriversCheck"] = "Netzwerk-/WLAN-Treiber dieses PCs hinzufügen", ["EjectWhenDoneCheck"] = "Laufwerk nach Abschluss auswerfen", ["UseDismEngineCheck"] = "Microsoft-Engine (DISM) verwenden", ["UseNtfsRawEngineCheck"] = "Schnelles Klonen", ["OpenReportButton"] = "Letzten Bericht öffnen", ["ScheduleCloneButton"] = "Diesen Klon planen (automatisches Backup)…", ["StartBackup"] = "In Abbilddatei sichern", ["SbCleanT"] = "Spuren bereinigen", ["SbCleanS"] = "Speicher freigeben und Nutzungsspuren löschen", ["CleanPanelTitle"] = "Spuren bereinigen", ["CleanPanelDesc"] = "Geben Sie Speicherplatz frei und entfernen Sie die Nutzungsspuren, die Windows und Ihre Apps hinterlassen. Wählen Sie aus, was bereinigt werden soll, klicken Sie auf Analysieren, um zu sehen, wie viel frei wird, und dann auf Jetzt bereinigen. Nichts verlässt jemals Ihren PC.", ["ChkCleanTemp"] = "Temporäre Dateien (Windows + Apps)", ["ChkCleanRecent"] = "Zuletzt verwendete Dateien & Sprunglisten", ["ChkCleanThumbs"] = "Miniaturansicht-Cache", ["ChkCleanBrowser"] = "Browser-Caches (Edge, Chrome, Firefox)", ["ChkCleanPrefetch"] = "Windows-Prefetch", ["ChkCleanUpdate"] = "Windows Update-Cache", ["ChkCleanRecycle"] = "Papierkorb (alle Laufwerke)", ["ChkCleanDns"] = "DNS-Auflösungscache", ["ChkCleanClipboard"] = "Zwischenablage-Inhalt", ["CleanAnalyzeButton"] = "Analysieren", ["CleanRunButton"] = "Jetzt bereinigen", ["CleanSelectAllButton"] = "Alle auswählen", ["CleanNote"] = "Sicher konzipiert: Es werden nur Standard-Cache- und temporäre Speicherorte bereinigt, und in Verwendung befindliche Dateien werden übersprungen. Das Leeren des Papierkorbs löscht dessen Inhalt endgültig. Einige Elemente (Prefetch, Windows Update-Cache) erfordern Administratorrechte.", ["CleanAnalyzing"] = "Wird analysiert…", ["CleanAnalyzeResult"] = "Etwa {0} können freigegeben werden.", ["CleanAnalyzeAdvanced"] = "Weitere {0} liegen in den erweiterten Einträgen - setzen Sie das Häkchen bei [[CleanAdvancedToggle]], um sie einzubeziehen.", ["BzCleaning"] = "Wird aufgeräumt...", ["CleanNothingSelected"] = "Nichts ausgewählt.", ["CleanConfirmTitle"] = "Spuren bereinigen", ["CleanConfirmBody"] = "Dadurch werden die ausgewählten Elemente dauerhaft entfernt:", ["CleanCleaningX"] = "Bereinigen: {0}…", ["CleanDone"] = "Fertig — {0} freigegeben ({1} Dateien entfernt).", ["CleanStopped"] = "Angehalten — {0} freigegeben ({1} Dateien entfernt). {2} der angehakten Einträge wurden nicht bereinigt.", ["RecTypeAll"] = "Alle", ["RecTypePictures"] = "Bilder", ["RecTypeDocuments"] = "Dokumente", ["RecTypeAudio"] = "Audio", ["RecTypeVideo"] = "Video", ["RecTypeArchives"] = "Archive",
