ton"] = "Salva sessione…", ["RecoverOpenSessionButton"] = "Apri sessione…", ["RecoverZipTitle"] = "Recupera i file selezionati in uno zip", ["SessionSaveTitle"] = "Salva sessione di scansione", ["SessionOpenTitle"] = "Apri sessione di scansione", ["SessionNothing"] = "Esegui prima una scansione.", ["SessionSaved"] = "Sessione salvata — {0} file.", ["SessionLoaded"] = "Sessione caricata — {0} file da {1}.", ["PreviewSelect"] = "Seleziona un'immagine o un file di testo per l'anteprima.", ["PreviewNone"] = "Nessuna anteprima per questo tipo di file.", ["PreviewFail"] = "Anteprima non riuscita (danneggiato, troncato o non supportato).", ["A11yHelp"] = "Aiuto", ["A11ySearch"] = "Filtra i file", ["A11yTypeFilter"] = "Filtra per tipo di file", ["A11yTreemap"] = "Mappa dimensioni cartelle", ["LiveCompleted"] = "Completato 100%", ["LiveStopped"] = "Fermato", ["LiveSpeedTest"] = "Test velocità", ["LivePercent"] = "Test velocità {0}%", ["DescIsoWrite"] = "Scegli qualsiasi ISO avviabile (Linux, BSD, strumenti di ripristino, ecc.). DriveForge lo scrive sull'USB come immagine disco grezza, rendendolo avviabile su BIOS + UEFI.", ["Step2IsoImage"] = "Immagine ISO", ["Step2ImageFile"] = "File immagine", ["TbPartition"] = "Partizione", ["MvPartOption"] = "Sposta una partizione", ["ToolGrpDiagnose"] = "Diagnostica", ["ToolGrpMaintain"] = "Manutenzione", ["ToolGrpErase"] = "Cancellazione", ["MvGptVerifyFail"] = "DriveForge non è riuscito a verificare i checksum GPT di questo disco, quindi non rischierà uno spostamento — non è stato modificato nulla. (Il GPT potrebbe essere danneggiato o il disco usa un layout insolito.)", ["MvTitle"] = "Sposta una partizione", ["MvNoParts"] = "Nessuna partizione trovata nell'MBR di questo disco.", ["MvPickPart"] = "Quale partizione vuoi spostare?", ["MvDirPrompt"] = "Spostare la partizione verso l'inizio o la fine del disco?", ["MvLeft"] = "Verso l'inizio del disco", ["MvRight"] = "Verso la fine del disco", ["MvAmountPrompt"] = "Di quanti MB spostare la partizione?", ["MvOutOfRange"] = "Questo spostamento andrebbe oltre il bordo del disco o prima del primo 1 MB. Scegli un valore più piccolo.", ["MvOverlap"] = "Questo spostamento si sovrapporrebbe a un'altra partizione. Scegli un valore più piccolo o l'altra direzione.", ["MvConfirm"] = "Spostare la partizione #{0} ({1})?\n\n    Dall'offset {2}\n    All'offset {3}\n\n⚠ SPERIMENTALE. I dati della partizione vengono spostati fisicamente e la tabella delle partizioni viene riscritta.\n\n• Crea prima un'immagine del disco (Recupera → Crea immagine disco) in caso di problemi.\n• NON spegnere né scollegare durante lo spostamento — non può essere interrotto in sicurezza.\n\nContinuare?", ["MvWorking"] = "Spostamento della partizione — NON spegnere…", ["MvDone"] = "Fatto. La partizione #{0} è stata spostata. Se manca una lettera di unità, controlla Gestione dischi.", ["MvStopIgnored"] = "Hai premuto Interrompi e la richiesta è stata deliberatamente ignorata: lo spostamento di una partizione non può essere interrotto in sicurezza — a metà, la partizione esiste in due posti e non è leggibile in nessuno. È stato portato a termine. Non è stato danneggiato nulla.", ["MvFailed"] = "Impossibile spostare la partizione. La tabella delle partizioni è rimasta invariata.", ["PtResize"] = "Ridimensiona una partizione (espandi / riduci)", ["PtCreate"] = "Crea una partizione (nello spazio libero)", ["PtCreatePrompt"] = "Dimensione della nuova partizione in MB? (vuoto = tutto lo spazio non allocato)", ["PtCreateConfirm"] = "Creare una nuova partizione sul Disco {0} usando il suo spazio non allocato?\n\nLe partizioni esistenti non vengono toccate.", ["PtCreateDone"] = "Fatto. È stata creata una nuova partizione sul Disco {0}.", ["PtCreateFailed"] = "Impossibile creare una partizione — potrebbe non esserci spazio non allocato sul disco. Vedi i dettagli sotto.", ["PtDeleteFailed"] = "Il volume {0}: non è stato eliminato: Windows ha rifiutato. Potrebbe essere in uso oppure essere una partizione di sistema o di ripristino protetta. Vedi i dettagli qui sotto.", ["PtDelete"] = "Elimina una partizione (libera il suo spazio)", ["PtDeleteConfirm"] = "Eliminare il volume {0}: e trasformarlo in spazio non allocato?\n\n⚠ Tutto su {0}: verrà cancellato definitivamente. Operazione irreversibile.", ["PtDeleteDone"] = "Fatto. Il volume {0}: è stato eliminato; il suo spazio ora è non allocato.", ["PtResizePrompt"] = "Ridimensionare il volume {0}: — espandere o ridurre?", ["PtGrow"] = "Espandi (estendi nello spazio libero successivo)", ["PtShrink"] = "Riduci (libera spazio alla fine)", ["PtShrinkPrompt"] = "Quanti MB liberare da {0}: ? (max ≈ {1} MB)", ["PtGrowPrompt"] = "Quanti MB aggiungere a {0}: ? (vuoto = tutto lo spazio libero subito dopo)", ["PtBadAmount"] = "Inserisci un numero intero di megabyte.", ["PtShrinkConfirm"] = "Ridurre {0}: di {1} MB?\n\nLo spazio liberato diventa non allocato. I tuoi file vengono mantenuti.", ["PtGrowConfirm"] = "Espandere {0}: nello spazio non allocato che segue?", ["PtResizeWorking"] = "Ridimensionamento di {0}: …", ["PtResizeDone"] = "Fatto. Il volume {0}: è stato ridimensionato.", ["PtResizeFailed"] = "diskpart non è riuscito a ridimensionare il volume — vedi i dettagli sotto (es. nessuno spazio libero subito dopo, o limitato da file non spostabili).", ["PtNoDisk"] = "Seleziona prima un disco (Unità da testare).", ["PtSystemBlocked"] = "È un disco di sistema — DriveForge non ne modifica le partizioni.", ["PtTitle"] = "Strumenti partizione", ["PtPrompt"] = "Scegli un'azione per il Disco {0}:", ["PtQuickPart"] = "Partizione rapida (cancella e ricrea)", ["PtInit"] = "Inizializza un disco vuoto / RAW", ["PtConvert"] = "Converti MBR ↔ GPT (cancella il disco)", ["PtCheck"] = "Controlla il file system (CHKDSK)", ["PtActive"] = "Imposta la prima partizione attiva (flag di avvio MBR)", ["PtFindLost"] = "Trova partizioni perse (scansione di sola lettura)", ["PtConfirmBody"] = "{0} su questo disco?\n\n    Disco {1} — {2} — {3}\n\nAttualmente contiene:\n{4}\n\n⚠ Tutto verrà CANCELLATO. Operazione irreversibile.", ["PtWorking"] = "{0} sul disco selezionato…", ["PtCountPrompt"] = "Quante partizioni creare sul Disco {0}?", ["PtFsPrompt"] = "Scegli il file system per le nuove partizioni:", ["PtQuickDone"] = "Fatto. Il Disco {0} ora ha {1} × {2} partizione/i.", ["PtInitPrompt"] = "Inizializzare il Disco {0} con quale stile di partizione?", ["PtGpt"] = "GPT (moderno, >2 TB, UEFI)", ["PtMbr"] = "MBR (legacy, BIOS)", ["PtInitDone"] = "Fatto. Il Disco {0} è stato inizializzato e formattato (NTFS).", ["PtConvertDone"] = "Fatto. Il Disco {0} ora è {1}.", ["PtNoVolumes"] = "Questo disco non ha volumi formattati.",["PtGrowNoRoom"] = "{0}: non può crescere — non c'è spazio non allocato subito dopo.\n\nUna partizione può crescere solo nello spazio libero che la segue direttamente sul disco. Lo spazio prima, o dopo un'altra partizione, non è utilizzabile: elimina o sposta prima ciò che sta in mezzo.", ["PtPickVolume"] = "Quale volume vuoi controllare?", ["PtChecking"] = "Controllo di {0}: …", ["PtCheckDone"] = "Controllo di {0}: completato.", ["PtActiveGpt"] = "Su un disco GPT non esiste il flag 'attivo' — UEFI avvia dalla partizione di sistema EFI.", ["PtActiveConfirm"] = "Impostare la prima partizione del Disco {0} come attiva (avviabile)?", ["PtActiveDone"] = "Fatto. La prima partizione del Disco {0} ora è attiva.", ["PtActiveNotSet"] = "Disco {0}: la prima partizione non risulta ancora attiva. diskpart non ha segnalato errori, ma il flag non è cambiato: forse il disco non ha una partizione 1, oppure Windows ha rifiutato. Vedi i dettagli qui sotto.", ["PtQuickPartial"] = "Il disco {0} non è come richiesto: ha {1} partizione(i) sulle {2} richieste, e Windows vi rileva questi file system: {3}. diskpart si è fermato a metà senza segnalare errori. Vedi i dettagli qui sotto.", ["MbFormatNoFs"] = "Il disco {0} è stato partizionato, ma Windows non vi rileva un file system {1}: la formattazione non è stata completata, anche se diskpart non ha segnalato errori. L'unità non è ancora pronta all'uso. Vedi i dettagli qui sotto, poi riprova oppure formattala da Gestione disco.", ["PtScanningLost"] = "Scansione del Disco {0} alla ricerca di partizioni perse…", ["PtLostNone"] = "Nessuna firma di partizione trovata sul Disco {0}.", ["PtLostUnmounted"] = "non montata (forse persa)", ["PtLostFound"] = "Trovate {0} partizione/i sul Disco {1}:", ["PtLostHint"] = "Scansione di sola lettura — nessuna modifica è stata apportata. Per ripristinare una partizione persa, utilizza uno strumento dedicato di recupero partizioni; per recuperarne i file, crea un'immagine del disco ed esegui il recupero dall'immagine.",["PtLostStopped"] = "\n\nLa scansione non è terminata: questo è solo quanto era riuscita a raggiungere, il resto del disco non è stato esaminato.", ["WipeSsd"] = "Cancellazione SSD (TRIM — la cancellazione adatta agli SSD)", ["SsdConfirm"] = "Cancellazione SSD del Disco {0}?\n\n    {1} — {2}\n\nAttualmente contiene:\n{3}\n\n⚠ Tutti i dati saranno scartati. Operazione irreversibile.", ["SsdWorking"] = "Cancellazione del Disco {0} (formattazione rapida + TRIM)…", ["SsdDone"] = "Fatto. Il Disco {0} è stato pulito e cancellato con TRIM — su un SSD il controller scarta i vecchi blocchi di dati. Per una sanitizzazione certificata, esegui anche lo strumento Secure Erase del produttore.", ["RecPreviewLabel"] = "Anteprima", ["EjectDriveButton"] = "Rimozione sicura", ["AddAllDriversCheck"] = "Aggiungi TUTTI i driver di questo PC (più lento)", ["AddNetworkDriversCheck"] = "Aggiungi i driver di rete / Wi-Fi di questo PC", ["EjectWhenDoneCheck"] = "Espelli l'unità al termine", ["UseDismEngineCheck"] = "Usa il motore Microsoft (DISM)", ["UseNtfsRawEngineCheck"] = "Clonazione rapida", ["OpenReportButton"] = "Apri ultimo report", ["ScheduleCloneButton"] = "Pianifica questa clonazione (backup automatico)…", ["StartBackup"] = "Backup in file immagine", ["SbCleanT"] = "Pulizia tracce", ["SbCleanS"] = "Libera spazio ed elimina le tracce d'uso", ["CleanPanelTitle"] = "Pulizia tracce", ["CleanPanelDesc"] = "Recupera spazio su disco ed elimina le tracce d'uso lasciate da Windows e dalle tue app. Spunta cosa pulire, premi Analizza per vedere quanto libererai, poi Pulisci ora. Niente lascia mai il tuo PC.", ["ChkCleanTemp"] = "File temporanei (Windows + app)", ["ChkCleanRecent"] = "File recenti ed elenchi di collegamenti", ["ChkCleanThumbs"] = "Cache delle miniature", ["ChkCleanBrowser"] = "Cache dei browser (Edge, Chrome, Firefox)", ["ChkCleanPrefetch"] = "Prefetch di Windows", ["ChkCleanUpdate"] = "Cache di Windows Update", ["ChkCleanRecycle"] = "Cestino (tutte le unità)", ["ChkCleanDns"] = "Cache del resolver DNS", ["ChkCleanClipboard"] = "Contenuto degli appunti", ["CleanAnalyzeButton"] = "Analizza", ["CleanRunButton"] = "Pulisci ora", ["CleanSelectAllButton"] = "Seleziona tutto", ["CleanNote"] = "Sicuro per progettazione: vengono puliti solo i percorsi standard di cache e temporanei e i file in uso vengono saltati. Svuotare il Cestino ne elimina il contenuto in modo permanente. Alcuni elementi (Prefetch, cache di Windows Update) richiedono i diritti di amministratore.", ["CleanAnalyzing"] = "Analisi in corso…", ["CleanAnalyzeResult"] = "È possibile liberare circa {0}.", ["CleanAnalyzeAdvanced"] = "Altri {0} sono negli elementi avanzati: spunta [[CleanAdvancedToggle]] per includerli.", ["BzCleaning"] = "Pulizia in corso...", ["CleanNothingSelected"] = "Niente selezionato.", ["CleanConfirmTitle"] = "Pulizia tracce", ["CleanConfirmBody"] = "Questa operazione rimuoverà definitivamente gli elementi selezionati:", ["CleanCleaningX"] = "Pulizia: {0}…", ["CleanDone"] = "Fatto — liberati {0} ({1} file rimossi).", ["CleanStopped"] = "Interrotto — liberati {0} ({1} file rimossi). {2} delle voci selezionate non sono state pulite.", ["RecTypeAll"] = "Tutti", ["RecTypePictures"] = "Immagini", ["RecTypeDocuments"] = "Documenti", ["RecTypeAudio"] = "Audio", ["RecTypeVideo"] = "Video", ["