			["RecFilterLabel"] = "Filtrar", ["RecSelectAllButton"] = "Selecionar tudo", ["RecSelectNoneButton"] = "Limpar seleção", ["RecoverStopButton"] = "Parar", ["RecoverDeepScanButton"] = "Análise profunda", ["CreateImageButton"] = "Criar imagem de disco…", ["OpenImageButton"] = "Abrir imagem…", ["CleanTab1Header"] = "Limpar rastros", ["CleanTab2Header"] = "Espaço em disco", ["AnalyzePanelDesc"] = "Descubra o que ocupa seu disco: examine qualquer pasta ou unidade, veja um mapa de tamanho das subpastas, os maiores arquivos e as cópias duplicadas que você pode excluir com segurança. Somente leitura até você escolher excluir.", ["AnalyzeFolderLabel"] = "Pasta a examinar", ["AnalyzeBrowseButton"] = "Procurar…", ["AnalyzeScanButton"] = "Examinar", ["AnalyzeStopButton"] = "Parar", ["AnalyzeBigFilesTab"] = "Maiores arquivos", ["AnalyzeDupesTab"] = "Arquivos duplicados", ["AnalyzeKeepFirstButton"] = "Selecionar duplicados (manter 1)", ["AnalyzeDeleteButton"] = "Excluir seleção", ["AnalyzeNoFolder"] = "Escolha primeiro uma pasta para examinar.", ["AnalyzeScanning"] = "Examinando… {0}", ["AnalyzeHashing"] = "Procurando duplicados…", ["AnalyzeResult"] = "{0:N0} arquivos · {1} no total · maior subpasta: {2}", ["AnalyzeDupResult"] = "· {0} grupos de duplicados ({1} cópias extras, {2} recuperáveis)", ["AnalyzeDeleteTitle"] = "Excluir arquivos", ["AnalyzeDeleteDone"] = "{0} ficheiro(s) removidos — {1}. O que foi para a Reciclagem não liberta espaço até a esvaziares.", ["PredReplace"] = "Substituir em breve", ["PredWatch"] = "Vigiar esta unidade", ["PredHealthy"] = "Nenhum sinal de falha", ["PredUnknown"] = "Dados SMART insuficientes para prever", ["PredReasonHealth"] = "relata {0}", ["PredReasonUncorrected"] = "{0} erros de leitura / {1} de gravação não corrigíveis", ["PredReasonWear"] = "{0}% de desgaste", ["PredReasonErrors"] = "{0} erros registrados", ["PredReasonTemp"] = "temperatura alta ({0} °C)", ["RecoverZipButton"] = "Recuperar em ZIP…", ["RecoverSaveSessionButton"] = "Salvar