			["MbNoSpaceTitle"] = "Onvoldoende ruimte",
			["MbLocalAcctTitle"] = "Lokaal account",
			["MbDownloadTitle"] = "DriveForge — ISO downloaden",
			["MbKitCreated"] = "Diagnostische kit gemaakt:\n\n{0}",
			["MbWipeTitle"] = "DriveForge — veilig wissen",
			["Mb030"] = "Onvoldoende vrije ruimte om te testen. Maak de schijf eerst leeg of formatteer deze.",
			["MbWipeConfirm"] = "Deze schijf VEILIG WISSEN?\n\n    Schijf {0} — {1} — {2}\n\nDeze schijf bevat momenteel:\n{3}\n\n⚠ Elke sector wordt OVERSCHREVEN. Gegevens zijn NIET herstelbaar. Dit kan niet ongedaan worden gemaakt.", ["MbWipeConfirmQuick"] = "De partitietabel op deze schijf WISSEN?\n\n    Schijf {0} — {1} — {2}\n\nDeze schijf bevat momenteel:\n{3}\n\n⚠ U hebt de snelle methode gekozen, dus er wordt NIETS overschreven. De bestanden blijven fysiek op de schijf staan en zijn met herstelsoftware terug te halen. Kies een van de overschrijfmethoden als ze echt weg moeten.",
			["MbShredConfirm"] = "{0} bestand(en) permanent versnipperen?\n\nDe inhoud van elk bestand wordt overschreven ({1} doorgang(en)) en daarna verwijderd. Dit kan niet ongedaan worden gemaakt.\n\n(Let op: op SSD's/USB-flashgeheugen betekent wear-levelling dat enkele kopieën fysiek kunnen achterblijven; voor absolute zekerheid op flash voert u ook een volledige schijf-Wipe uit of gebruikt u de Secure Erase van de schijf.)",
			["DkNoLetter"] = "geen letter",			["DkSystemDisk"] = "WINDOWS ACTIEF (niet formatteren/wissen)",			["DkHealthOk"] = "Status: OK",			["DkHealth"] = "Status: {0}",
			["DkRow"] = "Schijf {0}",
			["DkInternalDisk"] = "interne schijf — geen verwisselbaar station",
			["MbConfirmSummary"] = "{0}\n\n    {1} — {2} — {3}\n\nDeze schijf bevat momenteel:\n{4}\n\n⚠ ALLES hierboven wordt GEWIST.\n\n{5}\n\nGeschatte tijd: {6}.{7}\n\nDoorgaan?",			["CoActClone"] = "Windows van DEZE pc klonen naar:",			["CoActRestore"] = "Een opgeslagen schijfkopie herstellen naar:",			["CoActCreate"] = "Windows-USB maken op:",			["CoOptions"] = "Opties: {0}.",			["CoOptionsNone"] = "Opties: standaard.",			["CoOptBitLocker"] = "Versleutelen met BitLocker (herstelsleutel wordt opgeslagen)",			["CoOptLocalAcct"] = "Microsoft-account overslaan (lokaal account maken)",			["CoOptBypassReq"] = "Windows 11-vereisten omzeilen",			["CoOptWholeDisk"] = "De hele schijf klonen (Windows + alle datapartities)",			["CoOptOtherParts"] = "Ook andere datapartities klonen",			["CoOptDataPart"] = "Een extra datapartitie maken",			["CoOptVerify"] = "Gekloonde gegevens achteraf verifiëren",			["CoOptCompact"] = "Compacte (ruimtebesparende) schijfkopie",			["CoSlowNote"] = "\n\nLet op: deze schijf kan traag zijn voor Windows To Go.",			["CoTitle"] = "Bevestigen — controleer dit",			["EstMinute"] = "ongeveer een minuut",			["EstMinutes"] = "ongeveer {0} minuten",			["EstHours"] = "ongeveer {0} uur", ["EstFromBurst"] = ", met de over 80 MB gemeten snelheid — een lange schrijfbewerking is vaak langzamer", ["EstNoTest"] = ", met een gebruikelijke schijfsnelheid — de snelheidstest is niet op deze schijf uitgevoerd",
			["MbShredWhat"] = "Te versnipperen, uit deze map:\n{0}\n\n{1} in {2} bestand(en), bijvoorbeeld:\n{3}\n\n",
			["MbSchedWeekly"] = "elke zondag",
			["Mb037"] = "Sluit de USB-schijf aan die u wilt gebruiken en probeer het opnieuw.",
			["Mb040"] = "Herstart DriveForge als administrator om een oppervlaktetest uit te voeren.",
			["Mb034"] = "Kon niet automatisch een actuele downloadlink vinden. Gebruik in plaats daarvan de knop op de officiële downloadpagina.",
			["MbFormatDone"] = "Klaar. Schijf {0} is geformatteerd als {1} en klaar voor gebruik.",
			["Mb031"] = "Dit is een systeemschijf — DriveForge voert hierop geen opstarttest uit.",
			["MbBootHelp"] = "\n\nHoe ervan op te starten: sluit de schijf aan op de doel-pc, zet hem aan en open het opstartmenu (meestal F12, F9, Esc of F2 direct na het inschakelen), kies daarna deze USB/SSD. De eerste keer opstarten duurt enkele minuten terwijl Windows de stuurprogramma's instelt.",
			["MbBitLockerNote"] = "\n\nLet op: BitLocker is nog op de achtergrond aan het versleutelen — houd de schijf aangesloten totdat deze 100% bereikt (manage-bde -status), anders voltooit het bij de eerste keer opstarten van de kloon.",
			["MbReinstallConfirm"] = "Opnieuw installeren WIST alle bestanden (inclusief uw ISO's) op Schijf {0}. Doorgaan?",
			["Mb028"] = "DriveForge voert de capaciteitstest niet uit op een systeemschijf.",
			["Mb042"] = "Selecteer eerst de te formatteren schijf ([[DiagDriveToTestLabel]]).",
			["Mb027"] = "Selecteer eerst de te testen schijf ([[DiagDriveToTestLabel]]).",
			["Mb045"] = "Herstart DriveForge als administrator om partities te beheren.",
			["Mb022"] = "Herstart DriveForge als administrator om schijven te wissen.",
			["MbMultiBootDone"] = "Klaar! Schijf {0} is nu een multi-boot USB.\n\nKopieer uw ISO-bestanden naar de zojuist geopende \"Ventoy\"-schijf — voeg er zoveel toe als erop passen (Windows, Linux, reparatietools).\n\nStart een willekeurige pc op vanaf deze schijf en kies een ISO uit het menu. Tip: gebruik [[TbTestBoot]] om te controleren of hij opstart.",
			["Mb021"] = "Dit is een systeemschijf — DriveForge wist deze niet.",
			["MbIsoTooBig"] = "De ISO ({0}) is groter dan de schijf ({1}).",
			["Mb018"] = "Dit is een systeemschijf — deze kan niet worden uitgeworpen.",
			["Mb015"] = "Er is nog geen rapport beschikbaar.",
			["Mb016"] = "Deze schijf heeft geen stationsletter. Formatteer deze eerst en wis daarna de vrije ruimte.",
			["Mb013"] = "De wachtwoorden komen niet overeen.",
			["MbNoFreeWipe"] = "Er is bijna geen vrije ruimte om te wissen op {0}:.",
			["MbSchedCreated"] = "Geplande taak \"DriveForge Auto Clone\" gemaakt.\n\nDeze kloont deze pc naar '{0}' {1} om 02:00, zolang die schijf is aangesloten.\n\nVerwijder hem op elk moment via Windows Task Scheduler (of hij wordt vervangen als u opnieuw een planning maakt).",
			["MbWipeFreeConfirm"] = "Vrije ruimte op {0}: wissen?\n\nUw bestaande bestanden worden NIET aangeraakt. DriveForge vult de {1} vrije ruimte met overschrijfgegevens ({2} doorgang(en)) en verwijdert deze daarna, zodat eerder verwijderde bestanden niet meer kunnen worden hersteld.\n\nDe schijf is tijdens het proces tijdelijk vol. Doorgaan?",
			["Mb038"] = "Multi-boot draait op de gratis, opensource Ventoy-engine (GPL-3.0). DriveForge moet deze eenmalig downloaden (~16 MB); daarna wordt deze in de cache opgeslagen voor offline gebruik.\n\nNu downloaden?",
			["Mb035"] = "Plak een directe http(s)-link naar een ISO-bestand.",
			["Mb032"] = "Herstart DriveForge als administrator om de opstarttest uit te voeren.",
			["Mb020"] = "Selecteer eerst de te wissen schijf ([[DiagDriveToTestLabel]]).",
			["MbBootTestOfflineWarn"] = "De opstarttest is voltooid, maar het weer online zetten van Schijf {0} is mogelijk mislukt.\n\nAls de schijf ontbreekt in Explorer, schakel deze opnieuw in via Disk Management, of voer in een admin PowerShell uit:\n    Set-Disk -Number {0} -IsOffline $false",
			["MbWriteIsoConfirm"] = "Deze ISO naar de USB schrijven als opstartbare afbeelding?\n\n    ISO: {0} ({1})\n    Naar: Schijf {2} — {3} — {4}\n\nDeze schijf bevat momenteel:\n{5}\n\n⚠ Alles op de schijf wordt GEWIST. (Werkt voor Linux en andere isohybrid-ISO's; een Windows-ISO kan beter worden gemaakt met \"[[SbCreateT]]\".)",
			["Mb041"] = "Niets geselecteerd.",
			["MbHyperV"] = "Voor de opstarttest is de Hyper-V-functie nodig, die niet is ingeschakeld op deze pc.\n\n\"Turn Windows features on or off\" openen zodat u Hyper-V kunt inschakelen? (Na het inschakelen is een herstart vereist.)",
			["Mb044"] = "Herstart DriveForge als administrator om schijven te formatteren.",
			["MbBootTestConfirm"] = "Deze schijf testen door op te starten in een virtuele machine?\n\n    Schijf {0} — {1} — {2}\n\nDriveForge gaat:\n• deze schijf offline halen (zodat de VM hem kan gebruiken),\n• een tijdelijke {3} VM starten die ervan opstart,\n• een venster openen zodat u het opstarten kunt bekijken.\n\nKijk alleen of het opstartmenu / logo verschijnt — voer GEEN installatieprogramma uit binnen de VM. Kom terug als u klaar bent en klik op OK om de test te stoppen en de schijf weer online te zetten.",
			["Mb019"] = "De schijf is leeggemaakt en uitgeworpen.\n\nAls Windows deze nog toont, wacht dan even en koppel hem los. (Interne SATA/NVMe-schijven kunnen mogelijk niet worden uitgeworpen — dat is normaal.)",
			["MbSurfaceConfirm"] = "Een alleen-lezen oppervlaktetest uitvoeren op:\n    Schijf {0} — {1} — {2}\n\nDriveForge leest elke sector om beschadigde/onleesbare blokken te vinden. Er wordt niets geschreven. Grote schijven kunnen even duren — gebruik Stop om te annuleren.",
			["MbVmRunning"] = "De opstarttest-VM draait en het venster is geopend.\n\n• Als u het opstartlogo / -menu van de schijf ziet, start hij correct op. ✓\n• Een zwart scherm of \"no bootable device\" betekent dat hij niet opstart — probeer de andere firmwaremodus (UEFI ↔ Legacy BIOS).\n\nKlik op OK wanneer u klaar bent om de test te stoppen en de schijf weer online te zetten.",
			["MbMultiBootTitle"] = "DriveForge — multi-boot USB",
			["Mb017"] = "Selecteer eerst de te verwijderen schijf.",
			["MbShredTitle"] = "DriveForge — veilig versnipperen", ["MbShredDone"] = "Klaar. {0} bestand(en) veilig gewist.", ["MbShredStopped"] = "Gestopt. {0} bestand(en) tot nu toe vernietigd.", ["MbShredNoReach"] = "\n\n⚠  {0} bestand(en) zijn verwijderd maar NIET overschreven. Ze zijn gecomprimeerd, ijl (sparse) of versleuteld, en Windows schrijft die naar nieuwe clusters in plaats van over de oude, dus de oorspronkelijke gegevens kunnen nog te herstellen zijn.", ["MbShredFailed"] = "\n\n{0} konden niet worden gewist (in gebruik of beveiligd).", ["MbShredLinks"] = "\n\n⚠ {0} item(s) zijn overgeslagen omdat het snelkoppelingen (symbolische links) naar bestanden elders zijn. Overschrijven zou het doelbestand hebben vernietigd, dat op een andere schijf kan staan. Wis die bestanden op de plek waar ze echt staan.",
			["MbCapacityTitle"] = "DriveForge — capaciteitstest",
			["MbCapacityConfirm"] = "De WERKELIJKE capaciteit verifiëren van:\n    {0} ({1}:) — claimt {2}\n\nDit schrijft ~{3} aan testgegevens naar de VRIJE ruimte, leest deze terug ter verificatie en verwijdert ze daarna. Uw bestaande bestanden worden NIET aangeraakt. Voer dit voor een volledige controle uit op een lege schijf.\n\nDoorgaan?",
			["MbDownloaded"] = "Gedownload:\n    {0}",
			["Mb001"] = "Selecteer eerst de doelschijf.",
