			["MbConfirmSummary"] = "{0}\n\n    {1} — {2} — {3}\n\nСейчас на этом диске:\n{4}\n\n⚠ ВСЁ перечисленное будет УДАЛЕНО.\n\n{5}\n\nПримерное время: {6}.{7}\n\nПродолжить?",			["CoActClone"] = "Клонировать Windows ЭТОГО ПК на:",			["CoActRestore"] = "Восстановить сохранённый образ на:",			["CoActCreate"] = "Создать USB с Windows на:",			["CoOptions"] = "Параметры: {0}.",			["CoOptionsNone"] = "Параметры: по умолчанию.",			["CoOptBitLocker"] = "Шифровать BitLocker (ключ восстановления сохраняется)",			["CoOptLocalAcct"] = "Пропустить учётную запись Microsoft (создать локальную)",			["CoOptBypassReq"] = "Обойти требования Windows 11",			["CoOptWholeDisk"] = "Клонировать весь диск (Windows + все разделы данных)",			["CoOptOtherParts"] = "Клонировать и другие разделы данных",			["CoOptDataPart"] = "Создать дополнительный раздел данных",			["CoOptVerify"] = "Проверить клонированные данные после",			["CoOptCompact"] = "Компактный образ (экономия места)",			["CoSlowNote"] = "\n\nПримечание: этот накопитель может быть медленным для Windows To Go.",			["CoTitle"] = "Подтверждение — проверьте",			["EstMinute"] = "около минуты",			["EstMinutes"] = "около {0} мин.",			["EstHours"] = "около {0} ч.", ["EstFromBurst"] = ", на скорости, измеренной на 80 MB, — длинная запись часто медленнее", ["EstNoTest"] = ", на типичной скорости накопителя — проверка скорости на этом накопителе не выполнялась",
			["MbShredWhat"] = "Будет уничтожено, из этой папки:\n{0}\n\n{1} в {2} файл(ах), например:\n{3}\n\n",
			["MbSchedWeekly"] = "каждое воскресенье",
			["Mb037"] = "Вставьте USB-накопитель, который хотите использовать, затем повторите попытку.",
			["Mb040"] = "Перезапустите DriveForge от имени администратора, чтобы запустить проверку поверхности.",
			["Mb034"] = "Не удалось автоматически найти актуальную ссылку для загрузки. Используйте вместо этого кнопку на официальной странице загрузки.",
			["MbFormatDone"] = "Готово. Диск {0} был отформатирован как {1} и готов к использованию.",
			["Mb031"] = "Это системный диск — DriveForge не будет проверять его загрузку.",
			["MbBootHelp"] = "\n\nКак с него загрузиться: подключите накопитель к целевому ПК, включите его и откройте меню загрузки (обычно F12, F9, Esc или F2 сразу после включения), затем выберите этот USB/SSD. Первая загрузка занимает несколько минут, пока Windows настраивает драйверы.",
			["MbBitLockerNote"] = "\n\nПримечание: BitLocker всё ещё шифрует в фоновом режиме — держите накопитель подключённым, пока он не достигнет 100% (manage-bde -status), иначе шифрование завершится при первой загрузке клона.",
			["MbReinstallConfirm"] = "Переустановка СОТРЁТ все файлы (включая ваши ISO) на диске {0}. Продолжить?",
			["Mb028"] = "DriveForge не будет выполнять проверку ёмкости на системном диске.",
			["Mb042"] = "Сначала выберите накопитель для форматирования ([[DiagDriveToTestLabel]]).",
			["Mb027"] = "Сначала выберите накопитель для проверки ([[DiagDriveToTestLabel]]).",
			["Mb045"] = "Перезапустите DriveForge от имени администратора, чтобы управлять разделами.",
			["Mb022"] = "Перезапустите DriveForge от имени администратора, чтобы очищать накопители.",
			["MbMultiBootDone"] = "Готово! Диск {0} теперь является мультизагрузочным USB.\n\nСкопируйте файлы ISO на накопитель «Ventoy», который только что открылся — добавьте столько, сколько поместится (Windows, Linux, средства восстановления).\n\nЗагрузите любой ПК с этого накопителя и выберите ISO из меню. Совет: используйте [[TbTestBoot]], чтобы убедиться, что он загружается.",
			["Mb021"] = "Это системный диск — DriveForge не будет его очищать.",
			["MbIsoTooBig"] = "ISO ({0}) больше, чем накопитель ({1}).",
			["Mb018"] = "Это системный диск — его нельзя извлечь.",
			["Mb015"] = "Отчёт пока недоступен.",
			["Mb016"] = "У этого накопителя нет буквы диска. Сначала отформатируйте его, затем очистите свободное пространство.",
			["Mb013"] = "Пароли не совпадают.",
			["MbNoFreeWipe"] = "На {0}: почти нет свободного места для очистки.",
			["MbSchedCreated"] = "Запланированная задача «DriveForge Auto Clone» создана.\n\nОна будет клонировать этот ПК на «{0}» {1} в 02:00, пока этот накопитель подключён.\n\nУдалить её можно в любой момент через Windows Task Scheduler (либо она заменяется при повторном планировании).",
			["MbWipeFreeConfirm"] = "Очистить свободное пространство на {0}:?\n\nВаши существующие файлы НЕ затрагиваются. DriveForge заполняет {1} свободного пространства данными перезаписи ({2} проход(ов)), а затем удаляет их, чтобы ранее удалённые файлы больше нельзя было восстановить.\n\nВо время процесса накопитель будет временно заполнен. Продолжить?",
			["Mb038"] = "Мультизагрузка работает на основе бесплатного движка с открытым исходным кодом Ventoy (GPL-3.0). DriveForge нужно один раз загрузить его (~16 МБ); затем он кэшируется для использования офлайн.\n\nЗагрузить его сейчас?",
			["Mb035"] = "Вставьте прямую ссылку http(s) на файл ISO.",
			["Mb032"] = "Перезапустите DriveForge от имени администратора, чтобы запустить проверку загрузки.",
			["Mb020"] = "Сначала выберите накопитель для очистки ([[DiagDriveToTestLabel]]).",
			["MbBootTestOfflineWarn"] = "Проверка загрузки завершена, но вернуть диск {0} в оперативный режим, возможно, не удалось.\n\nЕсли накопитель отсутствует в Explorer, снова включите его в Disk Management или выполните в PowerShell с правами администратора:\n    Set-Disk -Number {0} -IsOffline $false",
			["MbWriteIsoConfirm"] = "Записать этот ISO на USB как загрузочный образ?\n\n    ISO: {0} ({1})\n    На: диск {2} — {3} — {4}\n\nСейчас на этом диске находится:\n{5}\n\n⚠ Всё содержимое диска будет СТЁРТО. (Подходит для Linux и других isohybrid-образов ISO; ISO Windows лучше создавать через «[[SbCreateT]]».)",
			["Mb041"] = "Ничего не выбрано.",
			["MbHyperV"] = "Для проверки загрузки нужна функция Hyper-V, которая не включена на этом ПК.\n\nОткрыть «Turn Windows features on or off», чтобы включить Hyper-V? (После включения требуется перезагрузка.)",
			["Mb044"] = "Перезапустите DriveForge от имени администратора, чтобы форматировать накопители.",
			["MbBootTestConfirm"] = "Проверить загрузку этого накопителя в виртуальной машине?\n\n    Диск {0} — {1} — {2}\n\nDriveForge выполнит:\n• перевод этого диска в автономный режим (чтобы ВМ могла его использовать),\n• запуск временной ВМ {3}, которая загружается с него,\n• открытие окна, чтобы вы могли наблюдать за загрузкой.\n\nПросто следите, чтобы дошло до меню загрузки / логотипа — НЕ запускайте установщик внутри ВМ. Когда закончите, вернитесь сюда и нажмите OK, чтобы остановить проверку и вернуть диск в оперативный режим.",
			["Mb019"] = "Накопитель был сброшен и извлечён.\n\nЕсли Windows всё ещё показывает его, подождите немного, затем отключите. (Внутренние диски SATA/NVMe могут не извлекаться — это нормально.)",
			["MbSurfaceConfirm"] = "Запустить проверку поверхности (только чтение) для:\n    Диск {0} — {1} — {2}\n\nDriveForge считывает каждый сектор для поиска повреждённых/нечитаемых блоков. Ничего не записывается. Большие накопители могут потребовать времени — используйте Stop для отмены.",
			["MbVmRunning"] = "ВМ для проверки загрузки запущена, и её окно открыто.\n\n• Если вы видите логотип / меню загрузки накопителя, он загружается корректно. ✓\n• Чёрный экран или «no bootable device» означает, что он не загружается — попробуйте другой режим прошивки (UEFI ↔ Legacy BIOS).\n\nНажмите OK, когда закончите, чтобы остановить проверку и вернуть диск в оперативный режим.",
			["MbMultiBootTitle"] = "DriveForge — мультизагрузочный USB",
			["Mb017"] = "Сначала выберите накопитель для удаления.",
			["MbShredTitle"] = "DriveForge — безопасное уничтожение", ["MbShredDone"] = "Готово. Надёжно удалено файлов: {0}.", ["MbShredStopped"] = "Остановлено. Уничтожено файлов: {0}.", ["MbShredNoReach"] = "\n\n⚠  Файлов удалено без перезаписи: {0}. Они сжаты, разрежены или зашифрованы, и Windows записывает такие файлы в новые кластеры вместо старых, поэтому исходные данные всё ещё могут быть восстановлены.", ["MbShredFailed"] = "\n\nНе удалось удалить: {0} (заняты или защищены).", ["MbShredLinks"] = "\n\n⚠ Пропущено элементов: {0} — это ярлыки (символические ссылки) на файлы в другом месте. Перезапись уничтожила бы файл, на который они указывают, а он может быть на другом диске. Удаляйте такие файлы там, где они действительно находятся.",
			["MbCapacityTitle"] = "DriveForge — проверка ёмкости",
			["MbCapacityConfirm"] = "Проверить РЕАЛЬНУЮ ёмкость:\n    {0} ({1}:) — заявлено {2}\n\nЭто записывает ~{3} тестовых данных в СВОБОДНОЕ пространство, считывает их обратно для проверки, затем удаляет. Ваши существующие файлы НЕ затрагиваются. Для полной проверки запустите её на пустом накопителе.\n\nПродолжить?",
			["MbDownloaded"] = "Загружено:\n    {0}",
			["Mb001"] = "Сначала выберите целевой накопитель.",
			["Mb002"] = "Не удалось определить путь к приложению для планирования.",
			["BzBootVm"] = "Запуск ВМ для проверки загрузки диска {0}...",
			["MbUsbDone"] = "Создание USB завершено.",
			["MbRestoreDone"] = "Восстановление завершено.",
			["HiveStepPortable"] = "настройки переносной Windows",
			["BcdbootFailed"] = "Windows не записал загрузочные файлы, поэтому этот накопитель не запустится. Всё остальное скопировано, но без загрузочной записи диск не загрузится.",
			["BcdStoreCollision"] = "Загрузочную запись не удалось создать, потому что этот ПК отказывается её подключить — это та же блокировка, из-за которой DriveForge не может открыть реестр внутри образа, и почти всегда это антивирус или защитный пакет. Отключите эту защиту на несколько минут и попробуйте снова: ни с накопителем, ни с образом ничего не случилось.",
			["HiveBlockedWarn"] = "⚠ Этот компьютер не даёт DriveForge открыть реестр внутри образа — почти всегда это блокирует антивирус или защитный пакет.\n\nКлонирование этого ПК остановится на полпути. USB с Windows всё равно будет создан и будет загружаться, но настройки, которые записываются в образ после этого (настройки переносной Windows, обход требований Windows 11, обход учётной записи Microsoft, удаление лишних программ), будут отсутствовать.\n\nОбычно достаточно отключить эту защиту на несколько минут.",
			["BitLockerEditionWarn"] = "⚠ Эта редакция Windows не может включить BitLocker. Управление BitLocker есть только в Windows Pro, Enterprise и Education — Home отказывает с ошибкой 0x8031005A.\n\nВсё остальное выполнится ровно так, как описано, и диск будет работать. Он просто не будет зашифрован, и ключ восстановления не будет создан.\n\nСнимите галочку BitLocker, чтобы убрать это предупреждение, или запустите DriveForge на компьютере с одной из этих редакций.",
			["HiveBlockedDone"] = "Эти настройки не удалось записать в образ, потому что этот ПК блокирует доступ к оффлайн-реестру (почти всегда — антивирус): {0}.\n\nСам накопитель готов и загрузится — нет только этих настроек.",
			["Mb007"] = "Сначала выберите целевой USB/SSD.",
			["BzWiping"] = "Очистка диска {0} ({1})...",
			["MbSurfaceTitle"] = "DriveForge — проверка поверхности",
			["Mb008"] = "Выбранный диск помечен как системный/загрузочный. DriveForge не будет его форматировать.",
			["BzCapacity"] = "Проверка реальной ёмкости {0}:...",
			["Mb025"] = "Похоже, это ISO Windows / WinPE.\n\nISO-образы Windows не являются «isohybrid», поэтому их запись как необработанного образа обычно НЕ загружается. Для правильного создания загрузочного USB с Windows используйте задачу «[[SbCreateT]]».\n\nВсё равно записать как необработанный образ?",
			["Mb003"] = "Сначала выберите Windows ISO / WIM / ESD.",
			["BzVerify"] = "Проверка диска {0}...",
			["MbTestBootTitle"] = "DriveForge — проверка загрузки",
			["MbBackupCreated"] = "Резервный образ создан:\n\n{0}  ({1})\n\nЧтобы восстановить его позже: выберите «[[SbRestoreT]]», укажите этот .wim и выберите целевой накопитель.",
			["MbFormatConfirm"] = "Отформатировать (стереть) этот накопитель?\n\n    Диск {0} — {1} — {2}\n\nСейчас на этом диске находится:\n{3}\n\n⚠ ВСЁ перечисленное выше будет безвозвратно СТЁРТО.",
			["MbSchedDaily"] = "ежедневно",
			["MbBackupNoSpace"] = "Недостаточно свободного места там, где вы сохраняете образ.\n\nПримерно требуется места: ~{0}\nСвободно в месте назначения: {1}",
			["MbWriteIsoTitle"] = "DriveForge — запись ISO",
			["Mb014"] = "Пароли BitLocker должны содержать не менее 8 символов (либо оставьте оба поля пустыми для использования только ключа восстановления).",
			["BzShred"] = "Уничтожение файлов: {0}...",
			["Mb011"] = "Перезапустите DriveForge от имени администратора, чтобы создать резервный образ.",
			["Mb012"] = "Введите допустимое имя учётной записи (без специальных символов).",
			["Mb039"] = "Сначала выберите накопитель для проверки.",
			["Mb036"] = "Перезапустите DriveForge от имени администратора, чтобы создать мультизагрузочный USB.",
			["Mb006"] = "Остановить текущую операцию? USB может остаться незавершённым, и его потребуется отформатировать заново.",
			["Mb033"] = "Сначала выберите дистрибутив из списка.",
			["MbFormatTitle"] = "DriveForge — форматирование накопителя",
			["Mb004"] = "Операция всё ещё выполняется. Закрытие приложения может оставить USB незавершённым. Вы уверены, что хотите закрыть?",
			["Mb009"] = "Сначала выберите исходный образ.",
			["MbWipeFreeTitle"] = "DriveForge — очистка свободного пространства",
			["Mb010"] = "Перезапустите DriveForge от имени администратора перед созданием USB.",
			["MbDiskChanged"] = "Целевой диск изменился с момента последнего сканирования — возможно, теперь в этой позиции находится другой диск. В целях безопасности операция отменена. Повторно просканируйте диски и попробуйте снова.",
			["MbHyperVTitle"] = "DriveForge — требуется Hyper-V",
			["BzWipeFree"] = "Очистка свободного пространства на {0}:...",
			["Mb043"] = "Это системный диск — DriveForge не будет его форматировать.",
			["BzFormat"] = "Форматирование диска {0} как {1}...",
			["Mb024"] = "Сначала выберите образ ISO.",
			["BzWriteIso"] = "Запись образа ISO на диск {0}...",
			["MbMultiBootSetup"] = "Настроить диск {0} как мультизагрузочный USB?\n\n    {1} — {2}\n\nСейчас на этом диске находится:\n{3}\n\n⚠ Накопитель будет СТЁРТ и настроен с движком мультизагрузки Ventoy. После этого вы просто копируете на него файлы ISO (Windows, Linux, что угодно) и выбираете один из меню при загрузке.",
			["MbCloneHelperCreated"] = "Вспомогательные файлы для клона текущего компьютера созданы:\n\n{0}\n\nПолный клон нельзя создать, пока эта Windows запущена. Загрузитесь в Windows PE, запустите скрипт захвата, затем выберите «Restore a full computer clone» в DriveForge.",
			["Mb029"] = "У выбранного диска нет буквы диска. Сначала используйте Форматирование, затем запустите проверку ёмкости.",
			["BzSurface"] = "Проверка поверхности диска {0}...",
			["Mb005"] = "Остановить текущую операцию? Текущий файл будет завершён или прерван, а следующий запуск сможет продолжить с уже скопированных корректных файлов.",
			["ErrSchedTask"] = "Не удалось создать запланированную задачу",
			["BzCleanVm"] = "Очистка тестовой ВМ загрузки...",
			["ErrStop"] = "Не удалось остановить", ["ErrDetail"] = "Техническая подробность:", ["OpStopped"] = "Остановлено по вашему запросу.", ["OpStoppedPartial"] = "Остановлено до конца копирования, поэтому на приёмнике осталось неполное содержимое. Запустите операцию заново с начала, чтобы получить пригодный результат.", ["PfHealthNotOk"] = "Накопитель сообщает о проблеме состояния ({0}), поэтому DriveForge на него не пишет. Сначала выполните проверки [[TbHealth]] и [[TbSurface]] или выберите другой накопитель.", ["ErrImageOnTarget"] = "Файл образа находится на том же накопителе, на который идёт запись, поэтому операция уничтожила бы сам образ. Сначала перенесите образ на другой накопитель. Ничего не изменено.", ["ErrImageGone"] = "Выбранный файл образа больше не существует. Ничего не изменено.", ["ErrOutOfSpaceTarget"] = "На приёмнике закончилось место, поэтому записанное неполно. Возьмите накопитель большего объёма.", ["ErrOpenDiskRead"] = "Не удалось открыть диск для чтения. Запустите DriveForge от имени администратора и повторите.", ["ErrOpenVolumeRead"] = "Не удалось открыть том {0}: для чтения. Запустите DriveForge от имени администратора и повторите.", ["ErrOpenDiskNumRead"] = "Не удалось открыть физический диск {0} для чтения. Запустите DriveForge от имени администратора и повторите.",
			["ErrFreeWipe"] = "Не удалось стереть свободное пространство",
			["ErrQuickPart"] = "Не удалось выполнить быстрое разбиение",
			["BzDownloading"] = "Загрузка ",
			["ErrReport"] = "Не удалось открыть отчёт",
			["ErrHealth"] = "Не удалось проверить состояние диска",
			["BzSha"] = "Вычисление SHA-256 образа...",
			["BzClone"] = "Форматирование и клонирование Windows...",
			["ErrMoveMbrRead"] = "Не удалось переместить [mbr-read]",
			["BzReadSmart"] = "Чтение данных SMART...",
