			["RecFilterLabel"] = "Filtruj", ["RecSelectAllButton"] = "Zaznacz wszystko", ["RecSelectNoneButton"] = "Odznacz wszystko", ["RecoverStopButton"] = "Zatrzymaj", ["RecoverDeepScanButton"] = "Głębokie skanowanie", ["CreateImageButton"] = "Utwórz obraz dysku…", ["OpenImageButton"] = "Otwórz obraz…", ["CleanTab1Header"] = "Czyść ślady", ["CleanTab2Header"] = "Miejsce na dysku", ["AnalyzePanelDesc"] = "Sprawdź, co zajmuje dysk: przeskanuj dowolny folder lub dysk, zobacz mapę rozmiarów podfolderów, największe pliki i duplikaty, które możesz bezpiecznie usunąć. Tylko do odczytu, dopóki nie zdecydujesz się usunąć.", ["AnalyzeFolderLabel"] = "Folder do skanowania", ["AnalyzeBrowseButton"] = "Przeglądaj…", ["AnalyzeScanButton"] = "Skanuj", ["AnalyzeStopButton"] = "Zatrzymaj", ["AnalyzeBigFilesTab"] = "Największe pliki", ["AnalyzeDupesTab"] = "Zduplikowane pliki", ["AnalyzeKeepFirstButton"] = "Zaznacz duplikaty (zostaw 1)", ["AnalyzeDeleteButton"] = "Usuń zaznaczone", ["AnalyzeNoFolder"] = "Najpierw wybierz folder do skanowania.", ["AnalyzeScanning"] = "Skanowanie… {0}", ["AnalyzeHashing"] = "Szukanie duplikatów…", ["AnalyzeResult"] = "{0:N0} plików · łącznie {1} · największy podfolder: {2}", ["AnalyzeDupResult"] = "· {0} grup duplikatów ({1} dodatkowych kopii, {2} do odzyskania)", ["AnalyzeDeleteTitle"] = "Usuwanie plików", ["AnalyzeDeleteDone"] = "Usunięto plików: {0} — {1}. To, co trafiło do Kosza, nie zwalnia miejsca, dopóki go nie opróżnisz.", ["PredReplace"] = "Wkrótce wymień", ["PredWatch"] = "Obserwuj ten dysk", ["PredHealthy"] = "Brak oznak awarii", ["PredUnknown"] = "Za mało danych SMART do prognozy", ["PredReasonHealth"] = "zgłasza {0}", ["PredReasonUncorrected"] = "{0} nieusuwalnych błędów odczytu / {1} zapisu", ["PredReasonWear"] = "zużycie {0}%", ["PredReasonErrors"] = "zarejestrowane błędy: {0}", ["PredReasonTemp"] = "wysoka temperatura ({0} °C)", ["RecoverZipButton"] = "Odzyskaj do ZIP…", ["RecoverSaveSessionButton"] = "Zapisz sesję…", ["RecoverOpenSessionButton"] = "Otwórz sesję…", ["RecoverZipTitle"] = "Odzyskaj zaznaczone pliki do zip", ["SessionSaveTitle"] = "Zapisz sesję skanowania", ["SessionOpenTitle"] = "Otwórz sesję skanowania", ["SessionNothing"] = "Najpierw uruchom skanowanie.", ["SessionSaved"] = "Sesja zapisana — pliki: {0}.", ["SessionLoaded"] = "Sesja wczytana — pliki: {0} z {1}.", ["PreviewSelect"] = "Wybierz obraz lub plik tekstowy do podglądu.", ["PreviewNone"] = "Brak podglądu dla tego typu pliku.", ["PreviewFail"] = "Nie można wyświetlić podglądu (uszkodzony, obcięty lub nieobsługiwany).", ["A11yHelp"] = "Pomoc", ["A11ySearch"] = "Filtruj pliki", ["A11yTypeFilter"] = "Filtruj według typu pliku", ["A11yTreemap"] = "Mapa rozmiarów folderów", ["LiveCompleted"] = "Ukończono 100%", ["LiveStopped"] = "Zatrzymano", ["LiveSpeedTest"] = "Test prędkości", ["LivePercent"] = "Test prędkości {0}%", ["DescIsoWrite"] = "Wybierz dowolny rozruchowy ISO (Linux, BSD, narzędzia ratunkowe itd.). DriveForge zapisze go na USB jako surowy obraz dysku, czyniąc go rozruchowym na BIOS + UEFI.", ["Step2IsoImage"] = "Obraz ISO", ["Step2ImageFile"] = "Plik obrazu", ["TbPartition"] = "Partycja", ["MvPartOption"] = "Przenieś partycję", ["ToolGrpDiagnose"] = "Diagnostyka", ["ToolGrpMaintain"] = "Konserwacja", ["ToolGrpErase"] = "Wymazywanie", ["MvGptVerifyFail"] = "DriveForge nie mógł zweryfikować sum kontrolnych GPT tego dysku, więc nie zaryzykuje przeniesienia — nic nie zmieniono. (GPT może być uszkodzony lub dysk ma nietypowy układ.)", ["MvTitle"] = "Przenieś partycję", ["MvNoParts"] = "Nie znaleziono partycji w MBR tego dysku.", ["MvPickPart"] = "Którą partycję chcesz przenieść?", ["MvDirPrompt"] = "Przenieść partycję w stronę początku czy końca dysku?", ["MvLeft"] = "W stronę początku dysku", ["MvRight"] = "W stronę końca dysku", ["MvAmountPrompt"] = "O ile MB przenieść partycję?", ["MvOutOfRange"] = "To przeniesienie wyszłoby poza krawędź dysku lub przed pierwszy 1 MB. Wybierz mniejszą wartość.", ["MvOverlap"] = "To przeniesienie nałożyłoby się na inną partycję. Wybierz mniejszą wartość lub drugi kierunek.", ["MvConfirm"] = "Przenieść partycję #{0} ({1})?\n\n    Z offsetu {2}\n    Do offsetu {3}\n\n⚠ EKSPERYMENTALNE. Dane partycji są fizycznie przenoszone, a tablica partycji przepisywana.\n\n• Najpierw utwórz obraz dysku (Odzyskiwanie → Utwórz obraz dysku) na wypadek problemów.\n• NIE wyłączaj ani nie odłączaj podczas przenoszenia — nie można go bezpiecznie przerwać.\n\nKontynuować?", ["MvWorking"] = "Przenoszenie partycji — NIE wyłączaj…", ["MvDone"] = "Gotowe. Partycja #{0} została przeniesiona. Jeśli brakuje litery dysku, sprawdź Zarządzanie dyskami.", ["MvStopIgnored"] = "Nacisnąłeś Zatrzymaj, a żądanie zostało celowo zignorowane: przenoszenia partycji nie da się bezpiecznie przerwać — w połowie partycja istnieje w dwóch miejscach i w żadnym nie jest czytelna. Pozwolono mu się zakończyć. Nic nie zostało uszkodzone.", ["MvFailed"] = "Nie udało się przenieść partycji. Tablica partycji pozostała bez zmian.", ["PtResize"] = "Zmień rozmiar partycji (powiększ / zmniejsz)", ["PtCreate"] = "Utwórz partycję (w wolnym miejscu)", ["PtCreatePrompt"] = "Rozmiar nowej partycji w MB? (puste = całe nieprzydzielone miejsce)", ["PtCreateConfirm"] = "Utworzyć nową partycję na Dysku {0}, używając nieprzydzielonego miejsca?\n\nIstniejące partycje pozostają nietknięte.", ["PtCreateDone"] = "Gotowe. Utworzono nową partycję na Dysku {0}.", ["PtCreateFailed"] = "Nie udało się utworzyć partycji — może brakować nieprzydzielonego miejsca na dysku. Zobacz szczegóły poniżej.", ["PtDeleteFailed"] = "Wolumin {0}: nie został usunięty — Windows odmówił. Może być w użyciu albo być chronioną partycją systemową lub odzyskiwania. Szczegóły poniżej.", ["PtDelete"] = "Usuń partycję (zwolnij miejsce)", ["PtDeleteConfirm"] = "Usunąć wolumin {0}: i zamienić go w nieprzydzielone miejsce?\n\n⚠ Wszystko na {0}: zostanie trwale usunięte. Nie można cofnąć.", ["PtDeleteDone"] = "Gotowe. Wolumin {0}: został usunięty; jego miejsce jest teraz nieprzydzielone.", ["PtResizePrompt"] = "Zmienić rozmiar woluminu {0}: — powiększyć czy zmniejszyć?", ["PtGrow"] = "Powiększ (rozszerz na wolne miejsce za nim)", ["PtShrink"] = "Zmniejsz (zwolnij miejsce na końcu)", ["PtShrinkPrompt"] = "Ile MB zwolnić z {0}: ? (maks ≈ {1} MB)", ["PtGrowPrompt"] = "Ile MB dodać do {0}: ? (puste = całe wolne miejsce zaraz za nim)", ["PtBadAmount"] = "Wpisz całkowitą liczbę megabajtów.", ["PtShrinkConfirm"] = "Zmniejszyć {0}: o {1} MB?\n\nZwolnione miejsce stanie się nieprzydzielone. Twoje pliki zostają zachowane.", ["PtGrowConfirm"] = "Powiększyć {0}: o nieprzydzielone miejsce, które następuje po nim?", ["PtResizeWorking"] = "Zmiana rozmiaru {0}: …", ["PtResizeDone"] = "Gotowe. Rozmiar woluminu {0}: został zmieniony.", ["PtResizeFailed"] = "diskpart nie mógł zmienić rozmiaru woluminu — zobacz szczegóły poniżej (np. brak wolnego miejsca tuż za nim lub ograniczenie przez nieprzenoszalne pliki).", ["PtNoDisk"] = "Najpierw wybierz dysk (Dysk do testu).", ["PtSystemBlocked"] = "To dysk systemowy — DriveForge nie modyfikuje jego partycji.", ["PtTitle"] = "Narzędzia partycji", ["PtPrompt"] = "Wybierz akcję dla Dysku {0}:", ["PtQuickPart"] = "Szybkie partycjonowanie (wyczyść i utwórz ponownie)", ["PtInit"] = "Inicjalizuj pusty / RAW dysk", ["PtConvert"] = "Konwertuj MBR ↔ GPT (czyści dysk)", ["PtCheck"] = "Sprawdź system plików (CHKDSK)", ["PtActive"] = "Ustaw pierwszą partycję jako aktywną (flaga rozruchu MBR)", ["PtFindLost"] = "Znajdź utracone partycje (skan tylko do odczytu)", ["PtConfirmBody"] = "{0} na tym dysku?\n\n    Dysk {1} — {2} — {3}\n\nObecnie zawiera:\n{4}\n\n⚠ Wszystko zostanie WYMAZANE. Nie można cofnąć.", ["PtWorking"] = "{0} na wybranym dysku…", ["PtCountPrompt"] = "Ile partycji utworzyć na Dysku {0}?", ["PtFsPrompt"] = "Wybierz system plików dla nowych partycji:", ["PtQuickDone"] = "Gotowe. Dysk {0} ma teraz {1} × {2} partycję(e).", ["PtInitPrompt"] = "Z jakim stylem partycji zainicjować Dysk {0}?", ["PtGpt"] = "GPT (nowoczesny, >2 TB, UEFI)", ["PtMbr"] = "MBR (starszy, BIOS)", ["PtInitDone"] = "Gotowe. Dysk {0} został zainicjowany i sformatowany (NTFS).", ["PtConvertDone"] = "Gotowe. Dysk {0} to teraz {1}.", ["PtNoVolumes"] = "Ten dysk nie ma sformatowanych woluminów.",["PtGrowNoRoom"] = "{0}: nie może się powiększyć — zaraz za nim nie ma nieprzydzielonego miejsca.\n\nPartycja może rosnąć tylko w wolne miejsce, które następuje bezpośrednio po niej na dysku. Miejsce przed nią albo za inną partycją się nie nadaje: usuń lub przenieś najpierw to, co jest pomiędzy.", ["PtPickVolume"] = "Który wolumin chcesz sprawdzić?", ["PtChecking"] = "Sprawdzanie {0}: …", ["PtCheckDone"] = "Sprawdzanie {0}: zakończone.", ["PtActiveGpt"] = "Na dysku GPT nie ma flagi 'aktywna' — UEFI uruchamia się z partycji systemowej EFI.", ["PtActiveConfirm"] = "Ustawić pierwszą partycję Dysku {0} jako aktywną (rozruchową)?", ["PtActiveDone"] = "Gotowe. Pierwsza partycja Dysku {0} jest teraz aktywna.", ["PtActiveNotSet"] = "Dysk {0}: pierwsza partycja nadal nie jest oznaczona jako aktywna. diskpart nie zgłosił błędu, ale flaga się nie zmieniła — dysk może nie mieć partycji 1 albo Windows odmówił. Szczegóły poniżej.", ["PtQuickPartial"] = "Dysk {0} nie wyszedł tak, jak proszono: ma {1} partycję(e) z {2} żądanych, a Windows zgłasza na nim takie systemy plików: {3}. diskpart zatrzymał się w połowie, nie zgłaszając błędu. Szczegóły poniżej.", ["MbFormatNoFs"] = "Dysk {0} został podzielony na partycje, ale Windows nie zgłasza na nim systemu plików {1} — formatowanie się nie dokończyło, choć diskpart nie zgłosił błędu. Napęd nie jest jeszcze gotowy do użytku. Szczegóły poniżej; spróbuj ponownie lub sformatuj go w Zarządzaniu dyskami.", ["PtScanningLost"] = "Skanowanie Dysku {0} w poszukiwaniu utraconych partycji…", ["PtLostNone"] = "Nie znaleziono sygnatur partycji na Dysku {0}.", ["PtLostUnmounted"] = "niezamontowana (możliwe, że utracona)", ["PtLostFound"] = "Znaleziono {0} partycję(e) na Dysku {1}:", ["PtLostHint"] = "Skanowanie tylko do odczytu — nic nie zostało zmienione. Aby przywrócić utraconą partycję, użyj dedykowanego narzędzia do odzyskiwania partycji; aby uratować jej pliki, utwórz obraz dysku i odzyskaj dane z obrazu.",["PtLostStopped"] = "\n\nSkanowanie nie zostało ukończone, więc to tylko tyle, ile zdążyło objąć - reszta dysku nie była przeszukana.", ["WipeSsd"] = "Wymazywanie SSD (TRIM — wymazywanie odpowiednie dla SSD)", ["SsdConfirm"] = "Wymazać SSD Dysk {0}?\n\n    {1} — {2}\n\nObecnie zawiera:\n{3}\n\n⚠ Wszystkie dane zostaną odrzucone. Nie można cofnąć.", ["SsdWorking"] = "Wymazywanie Dysku {0} (szybkie formatowanie + TRIM)…", ["SsdDone"] = "Gotowe. Dysk {0} został wyczyszczony i wymazany przez TRIM — w SSD kontroler odrzuca stare bloki danych. Dla certyfikowanego oczyszczenia uruchom też narzędzie Secure Erase producenta.", ["RecPreviewLabel"] = "Podgląd", ["EjectDriveButton"] = "Bezpiecznie usuń", ["AddAllDriversCheck"] = "Dodaj WSZYSTKIE sterowniki tego komputera (wolniej)", ["AddNetworkDriversCheck"] = "Dodaj sterowniki sieci / Wi-Fi tego komputera", ["EjectWhenDoneCheck"] = "Wysuń dysk po zakończeniu", ["UseDismEngineCheck"] = "Użyj silnika Microsoft (DISM)", ["UseNtfsRawEngineCheck"] = "Szybkie klonowanie", ["OpenReportButton"] = "Otwórz ostatni raport", ["ScheduleCloneButton"] = "Zaplanuj to klonowanie (automatyczna kopia)…", ["StartBackup"] = "Kopia zapasowa do pliku obrazu", ["SbCleanT"] = "Czyść ślady", ["SbCleanS"] = "Zwolnij miejsce i usuń ślady użycia", ["CleanPanelTitle"] = "Czyść ślady", ["CleanPanelDesc"] = "Odzyskaj miejsce na dysku i usuń ślady użycia pozostawione przez Windows i Twoje aplikacje. Zaznacz, co wyczyścić, kliknij Analizuj, aby zobaczyć, ile zwolnisz, a potem Wyczyść teraz. Nic nigdy nie opuszcza Twojego komputera.", ["ChkCleanTemp"] = "Pliki tymczasowe (Windows + aplikacje)", ["ChkCleanRecent"] = "Ostatnie pliki i listy szybkiego dostępu", ["ChkCleanThumbs"] = "Pamięć podręczna miniatur", ["ChkCleanBrowser"] = "Pamięć podręczna przeglądarek (Edge, Chrome, Firefox)", ["ChkCleanPrefetch"] = "Windows Prefetch", ["ChkCleanUpdate"] = "Pamięć podręczna Windows Update", ["ChkCleanRecycle"] = "Kosz (wszystkie dyski)", ["ChkCleanDns"] = "Pamięć podręczna DNS", ["ChkCleanClipboard"] = "Zawartość schowka", ["CleanAnalyzeButton"] = "Analizuj", ["CleanRunButton"] = "Wyczyść teraz", ["CleanSelectAllButton"] = "Zaznacz wszystko", ["CleanNote"] = "Bezpieczne z założenia: czyszczone są tylko standardowe lokalizacje pamięci podręcznej i tymczasowe, a używane pliki są pomijane. Opróżnienie Kosza trwale usuwa jego zawartość. Niektóre pozycje (Prefetch, pamięć Windows Update) wymagają uprawnień administratora.", ["CleanAnalyzing"] = "Analizowanie…", ["CleanAnalyzeResult"] = "Można zwolnić około {0}.", ["CleanAnalyzeAdvanced"] = "Kolejne {0} jest w elementach zaawansowanych - zaznacz [[CleanAdvancedToggle]], aby je uwzględnić.", ["BzCleaning"] = "Czyszczenie...", ["CleanNothingSelected"] = "Nic nie zaznaczono.", ["CleanConfirmTitle"] = "Czyść ślady", ["CleanConfirmBody"] = "Spowoduje to trwałe usunięcie wybranych elementów:", ["CleanCleaningX"] = "Czyszczenie: {0}…", ["CleanDone"] = "Gotowe — zwolniono {0} (usunięto plików: {1}).", ["CleanStopped"] = "Zatrzymano — zwolniono {0} (usunięto plików: {1}). Nie wyczyszczono {2} z zaznaczonych pozycji.", ["RecTypeAll"] = "Wszystkie", ["RecTypePictures"] = "Zdjęcia", ["RecTypeDocuments"] = "Dokumenty", ["RecTypeAudio"] = "Audio", ["RecTypeVideo"] = "Wideo", ["RecTypeArchives"] = "Archiwa",
