			["ShowPwLabel"] = "Parolayı göster",
			["BtnOk"] = "Tamam",
			["BlkPwdLabel"] = "Parola:",
			["EdImageIndexFallback"] = "Windows görüntüsü dizin {0}",
			["LocAcctIntro"] = "Yeni Windows için bir yerel hesap oluşturun; böylece ilk açılışta hiçbir zaman Microsoft hesabı istenmez.\nParolasız bir hesap için parola alanını boş bırakın.",
			["BlkPwdIntro"] = "Klon için bir BitLocker kilit açma parolası girin.\nYalnızca kurtarma anahtarıyla korumak için her iki alanı da boş bırakın.",
			["RfDeepPartialSuffix"] = "(kısmi — tarama {0} konumunda durdu; sürücünün geri kalanı aranmadı)", ["RfStDone"] = "Kurtarıldı", ["RfStPartialOut"] = "Verilerin yalnızca bir kısmı okunabildi", ["RfStEmptyOut"] = "Boş çıktı - içeriği zaten silinmişti", ["RfStFailOut"] = "Okunamadı", ["RfStNoPayload"] = "Bu kayıtlı oturumda bu dosya için kurtarma verisi yok - sürücüyü yeniden taratın", ["RfStCarved"] = "İçeriğinden bulundu - parçalanmış olabilir", ["RfCappedSuffix"] = "(liste {0} kayıtta doldu - ötesindekiler listelenmedi)", ["RfGalleryNoneLeft"] = "Burada bulunan fotoğraflarda kurtarılabilir veri kalmamış, bu yüzden hiçbiri seçilemez.", ["RfVolNoFs"] = "okunabilir dosya sistemi yok", ["RfVolNoLabel"] = "etiketsiz", ["RfNoFsUseDeep"] = "{0}: sürücüsünde okunabilir bir dosya sistemi yok, dolayısıyla okunacak bir dosya listesi de yok. Yerine [[RecoverDeepScanButton]] kullanın - sürücünün içeriğinde doğrudan arar ve dosya sistemine ihtiyaç duymaz.", ["RfFilterShown"] = "({1} kaydın {0} tanesi gösteriliyor)", ["RfRecRetryNote"] = "\n\nBütün hâlde çıkmayan her satır işaretli kaldı ve [[RfColStatus]] sütununda ona ne olduğu yazıyor.",
			["RfSameDiskUnsure"] = "DriveForge, hedefin kurtarma yapılan diskten FARKLI bir fiziksel diskte olduğunu doğrulayamadı. Aynı diske kurtarmak, geri almaya çalıştığınız verilerin üzerine yazabilir. Yine de devam edilsin mi?",
			["WipeVssWarnAny"] = "Not: bu sürücüdeki boş alanı silmek, eski geri yükleme noktalarını, Dosya Geçmişi sürümlerini ve orada saklanan 'Önceki Sürümler'i kaldırabilir.",
			["CleanBinKept"] = "Geri Dönüşüm Kutusu korundu — 'Geri Dönüşüm Kutusuna gönder' seçtiğiniz için, boşaltmak saklamak istediğiniz şeyi yok ederdi.",
			["SecureDelNoReachNote"] = "Bu dosya sıkıştırılmış, seyrek (sparse) veya şifreli; bu yüzden Windows her üzerine yazmayı YENİ kümelere yazar ve orijinal veriyi diskte dokunulmadan bırakır. DriveForge bu nedenle güvenli silme taklidi yapmak yerine dosyayı normal şekilde siler.",
			["MbWipeFreeDoneHdd"] = "Tamamlandı. {0}: sürücüsündeki boş alanın üzerine yazıldı — daha önce silinen dosyalar artık kurtarılamaz.",
			["MbWipeFreeDoneFlash"] = "Tamamlandı. {0}: sürücüsündeki boş alanın üzerine yazıldı.\n\nNot: flash bellekte (SSD, USB bellek, hafıza kartı) bu, eski verilerin gittiğini GARANTİ ETMEZ — aşınma dengeleme, işletim sisteminin erişemediği kopyaları saklar.",
			["MbWipeFreeStopped"] = "Durduruldu. {0}: sürücüsündeki boş alanın yalnızca bir kısmının üzerine yazıldı.", ["MbWipeDoneQuick"] = "Tamamlandı. {0} numaralı diskin bölüm tablosu temizlendi ({1}).\n\n⚠  Verilerin kendisi ÜZERİNE YAZILMADI ve kurtarma araçlarıyla hâlâ geri getirilebilir. Geri alınamayan bir silme için Wipe işlemini yeniden çalıştırın ve üzerine yazan yöntemlerden birini seçin.\n\nDiski yeniden kullanmak için Biçimlendir seçeneğini kullanın.", ["MbWipeDoneOverwrite"] = "Tamamlandı. {0} numaralı diskin üzerine yazıldı ({1}). Önceki içerik kurtarılamaz.\n\nDiski yeniden kullanmak için Biçimlendir seçeneğini kullanın.", ["MbWipeStopped"] = "Silme durduruldu. {0} numaralı diskin üzerine yalnızca kısmen yazıldı, bu nedenle önceki verilerin bir kısmı hâlâ kurtarılabilir.",
			["CleanDoneRecycled"] = "{0} ({1} dosya) Geri Dönüşüm Kutusu'na taşındı — onu boşaltmadan yer açılmaz.",
			["RfRecPartialNote"] = "\n\n{0} yalnızca KISMEN kurtarıldı — eksik kısımlar okunamıyor veya zaten üzerine yazılmış. Kısmi dosyalar saklandı.",
			["RfRecEmptyNote"] = "\n\n{0} tanesi BOŞ geldi — dosya adları ve boyutları korundu, ama sürücü içeriği çoktan silmişti, okunacak bir şey kalmamıştı. SSD'de bu normaldir (TRIM) ve hiçbir araç bunu geri alamaz.", ["RfRecStoppedNote"] = "\n\n{0} hiç denenmedi, çünkü kurtarma durduruldu. Bunlar test EDİLMEDİ, dolayısıyla hâlâ kurtarılabilir olabilirler — onları seçip kurtarmayı yeniden çalıştırın.",
			["RfDeepFoundPartial"] = "İçeriğe göre {0} dosya bulundu — tarama {1} konumunda DURDURULDU, bu yüzden sürücünün geri kalanı aranmadı.",
