			["MbConfirmSummary"] = "{0}\n\n    {1} — {2} — {3}\n\nЗараз на цьому диску:\n{4}\n\n⚠ УСЕ перелічене буде ВИДАЛЕНО.\n\n{5}\n\nОрієнтовний час: {6}.{7}\n\nПродовжити?",			["CoActClone"] = "Клонувати Windows ЦЬОГО ПК на:",			["CoActRestore"] = "Відновити збережений образ на:",			["CoActCreate"] = "Створити USB із Windows на:",			["CoOptions"] = "Параметри: {0}.",			["CoOptionsNone"] = "Параметри: за замовчуванням.",			["CoOptBitLocker"] = "Шифрувати BitLocker (ключ відновлення зберігається)",			["CoOptLocalAcct"] = "Пропустити обліковий запис Microsoft (створити локальний)",			["CoOptBypassReq"] = "Обійти вимоги Windows 11",			["CoOptWholeDisk"] = "Клонувати весь диск (Windows + усі розділи даних)",			["CoOptOtherParts"] = "Клонувати також інші розділи даних",			["CoOptDataPart"] = "Створити додатковий розділ даних",			["CoOptVerify"] = "Перевірити клоновані дані після завершення",			["CoOptCompact"] = "Компактний образ (економія місця)",			["CoSlowNote"] = "\n\nПримітка: цей накопичувач може бути повільним для Windows To Go.",			["CoTitle"] = "Підтвердження — перевірте",			["EstMinute"] = "близько хвилини",			["EstMinutes"] = "близько {0} хв",			["EstHours"] = "близько {0} год", ["EstFromBurst"] = ", на швидкості, виміряній на 80 MB, — довгий запис часто повільніший", ["EstNoTest"] = ", на типовій швидкості накопичувача — перевірку швидкості на цьому диску не виконували",
			["MbShredWhat"] = "Буде знищено, з цієї теки:\n{0}\n\n{1} у {2} файл(ах), наприклад:\n{3}\n\n",
			["MbSchedWeekly"] = "щонеділі",
			["Mb037"] = "Вставте USB-диск, який ви хочете використати, і спробуйте знову.",
			["Mb040"] = "Перезапустіть DriveForge від імені адміністратора, щоб запустити тест поверхні.",
			["Mb034"] = "Не вдалося автоматично знайти актуальне посилання для завантаження. Скористайтеся натомість кнопкою на офіційній сторінці завантаження.",
			["MbFormatDone"] = "Готово. Диск {0} відформатовано як {1}, і він готовий до використання.",
			["Mb031"] = "Це системний диск — DriveForge не виконуватиме тест завантаження на ньому.",
			["MbBootHelp"] = "\n\nЯк завантажитися з нього: під’єднайте диск до цільового ПК, увімкніть його та відкрийте меню завантаження (зазвичай F12, F9, Esc або F2 одразу після ввімкнення), потім виберіть цей USB/SSD. Перше завантаження триває кілька хвилин, поки Windows налаштовує драйвери.",
			["MbBitLockerNote"] = "\n\nПримітка: BitLocker усе ще шифрує у фоновому режимі — тримайте диск підключеним, доки він не досягне 100% (manage-bde -status), інакше шифрування завершиться під час першого завантаження клона.",
			["MbReinstallConfirm"] = "Перевстановлення СТЕРЕ всі файли (зокрема ваші ISO) на диску {0}. Продовжити?",
			["Mb028"] = "DriveForge не виконуватиме тест ємності на системному диску.",
			["Mb042"] = "Спочатку виберіть диск для форматування ([[DiagDriveToTestLabel]]).",
			["Mb027"] = "Спочатку виберіть диск для тестування ([[DiagDriveToTestLabel]]).",
			["Mb045"] = "Перезапустіть DriveForge від імені адміністратора, щоб керувати розділами.",
			["Mb022"] = "Перезапустіть DriveForge від імені адміністратора, щоб очищати диски.",
			["MbMultiBootDone"] = "Готово! Диск {0} тепер є мультизавантажувальним USB.\n\nСкопіюйте свої файли ISO на диск \"Ventoy\", який щойно відкрився — додайте стільки, скільки вмістить (Windows, Linux, рятувальні інструменти).\n\nЗавантажте будь-який ПК із цього диска та виберіть ISO з меню. Порада: скористайтеся [[TbTestBoot]], щоб перевірити, чи він завантажується.",
			["Mb021"] = "Це системний диск — DriveForge не очищатиме його.",
			["MbIsoTooBig"] = "ISO ({0}) більший за диск ({1}).",
			["Mb018"] = "Це системний диск — його не можна вилучити.",
			["Mb015"] = "Звіт ще недоступний.",
			["Mb016"] = "У цього диска немає літери. Спочатку відформатуйте його, потім очистіть його вільний простір.",
			["Mb013"] = "Паролі не збігаються.",
			["MbNoFreeWipe"] = "На {0}: майже немає вільного місця для очищення.",
			["MbSchedCreated"] = "Заплановане завдання \"DriveForge Auto Clone\" створено.\n\nВоно клонуватиме цей ПК на «{0}» {1} о 02:00, доки цей диск підключено.\n\nВидалити його можна будь-коли через \"Task Scheduler\" Windows (або воно замінюється, якщо запланувати знову).",
			["MbWipeFreeConfirm"] = "Очистити вільний простір на {0}:?\n\nВаші наявні файли НЕ зачіпаються. DriveForge заповнює {1} вільного місця даними перезапису ({2} прохід(ів)), а потім видаляє їх, тож раніше видалені файли більше неможливо відновити.\n\nПід час процесу диск буде тимчасово заповнений. Продовжити?",
			["Mb038"] = "Мультизавантаження працює на безкоштовному рушії Ventoy з відкритим кодом (GPL-3.0). DriveForge потрібно завантажити його один раз (~16 МБ); потім він кешується для офлайн-використання.\n\nЗавантажити його зараз?",
			["Mb035"] = "Вставте пряме посилання http(s) на файл ISO.",
			["Mb032"] = "Перезапустіть DriveForge від імені адміністратора, щоб запустити тест завантаження.",
			["Mb020"] = "Спочатку виберіть диск для очищення ([[DiagDriveToTestLabel]]).",
			["MbBootTestOfflineWarn"] = "Тест завантаження завершено, але повернення диска {0} в онлайн могло не вдатися.\n\nЯкщо диск відсутній у Explorer, увімкніть його знову в \"Disk Management\" або виконайте в адміністраторському PowerShell:\n    Set-Disk -Number {0} -IsOffline $false",
			["MbWriteIsoConfirm"] = "Записати цей ISO на USB як завантажувальний образ?\n\n    ISO: {0} ({1})\n    На: диск {2} — {3} — {4}\n\nЗараз цей диск містить:\n{5}\n\n⚠ Усе на диску буде СТЕРТО. (Працює для Linux та інших isohybrid ISO; ISO Windows краще створювати через \"[[SbCreateT]]\".)",
			["Mb041"] = "Нічого не вибрано.",
			["MbHyperV"] = "Для тесту завантаження потрібна функція Hyper-V, яка не ввімкнена на цьому ПК.\n\nВідкрити \"Turn Windows features on or off\", щоб ви могли ввімкнути Hyper-V? (Після ввімкнення потрібен перезапуск.)",
			["Mb044"] = "Перезапустіть DriveForge від імені адміністратора, щоб форматувати диски.",
			["MbBootTestConfirm"] = "Протестувати завантаження цього диска у віртуальній машині?\n\n    Диск {0} — {1} — {2}\n\nDriveForge виконає такі дії:\n• переведе цей диск в офлайн (щоб VM могла його використати),\n• запустить тимчасову {3} VM, яка завантажується з нього,\n• відкриє вікно, щоб ви могли спостерігати за завантаженням.\n\nПросто простежте, щоб воно дійшло до меню завантаження / логотипа — НЕ запускайте інсталятор усередині VM. Коли закінчите, поверніться сюди й натисніть OK, щоб зупинити тест і повернути диск в онлайн.",
			["Mb019"] = "Дані на диск записано, і його вилучено.\n\nЯкщо Windows усе ще показує його, зачекайте хвильку, а потім від’єднайте. (Внутрішні диски SATA/NVMe можуть не вилучатися — це нормально.)",
			["MbSurfaceConfirm"] = "Виконати тест поверхні лише для читання на:\n    диск {0} — {1} — {2}\n\nDriveForge зчитує кожен сектор, щоб знайти пошкоджені/нечитані блоки. Нічого не записується. Великі диски можуть тестуватися довго — натисніть Stop, щоб скасувати.",
			["MbVmRunning"] = "VM для тесту завантаження запущено, і її вікно відкрилося.\n\n• Якщо ви бачите логотип / меню завантаження диска, він завантажується правильно. ✓\n• Чорний екран або \"no bootable device\" означає, що він не завантажується — спробуйте інший режим прошивки (UEFI ↔ \"Legacy BIOS\").\n\nНатисніть OK, коли закінчите, щоб зупинити тест і повернути диск в онлайн.",
			["MbMultiBootTitle"] = "DriveForge — мультизавантажувальний USB",
			["Mb017"] = "Спочатку виберіть диск для видалення.",
			["MbShredTitle"] = "DriveForge — безпечне знищення", ["MbShredDone"] = "Готово. Надійно видалено файлів: {0}.", ["MbShredStopped"] = "Зупинено. Знищено файлів: {0}.", ["MbShredNoReach"] = "\n\n⚠  Файлів видалено без перезапису: {0}. Вони стиснуті, розріджені або зашифровані, і Windows записує такі файли в нові кластери замість старих, тому вихідні дані все ще можуть бути відновлені.", ["MbShredFailed"] = "\n\nНе вдалося видалити: {0} (використовуються або захищені).", ["MbShredLinks"] = "\n\n⚠ Пропущено елементів: {0} — це ярлики (символічні посилання) на файли в іншому місці. Перезапис знищив би файл, на який вони вказують, а він може бути на іншому диску. Видаляйте такі файли там, де вони справді розташовані.",
			["MbCapacityTitle"] = "DriveForge — тест ємності",
			["MbCapacityConfirm"] = "Перевірити РЕАЛЬНУ ємність:\n    {0} ({1}:) — заявлено {2}\n\nЦе записує ~{3} тестових даних у ВІЛЬНЕ місце, зчитує їх назад для перевірки, а потім видаляє. Ваші наявні файли НЕ зачіпаються. Для повної перевірки виконайте це на порожньому диску.\n\nПродовжити?",
			["MbDownloaded"] = "Завантажено:\n    {0}",
			["Mb001"] = "Спочатку виберіть цільовий диск.",
			["Mb002"] = "Не вдалося визначити шлях до застосунку для планування.",
			["BzBootVm"] = "Запуск VM для тесту завантаження диска {0}...",
			["MbUsbDone"] = "Створення USB завершено.",
			["MbRestoreDone"] = "Відновлення завершено.",
			["HiveStepPortable"] = "налаштування портативної Windows",
			["BcdbootFailed"] = "Windows не записав файли завантаження, тож цей носій не запуститься. Усе інше скопійовано, але без завантажувального запису диск не завантажиться.",
			["BcdStoreCollision"] = "Завантажувальний запис не вдалося створити, бо цей ПК відмовляється його підключити — те саме блокування, через яке DriveForge не може відкрити реєстр усередині образу, і майже завжди це антивірус або захисний пакет. Вимкніть цей захист на кілька хвилин і спробуйте знову: ні з носієм, ні з образом нічого не сталося.",
			["HiveBlockedWarn"] = "⚠ Цей комп'ютер не дає DriveForge відкрити реєстр усередині образу — майже завжди це блокує антивірус або захисний пакет.\n\nКлонування цього ПК зупиниться на півдорозі. USB із Windows все одно буде створено й він завантажиться, але налаштувань, які записуються в образ після цього (налаштування портативної Windows, обхід вимог Windows 11, обхід облікового запису Microsoft, видалення зайвих програм), бракуватиме.\n\nЗазвичай достатньо вимкнути цей захист на кілька хвилин.",
			["BitLockerEditionWarn"] = "⚠ Ця редакція Windows не може увімкнути BitLocker. Керування BitLocker є лише у Windows Pro, Enterprise та Education — Home відмовляє з помилкою 0x8031005A.\n\nУсе інше виконається саме так, як описано, і диск працюватиме. Він просто не буде зашифрований, і ключ відновлення не створиться.\n\nЗніміть позначку BitLocker, щоб прибрати це попередження, або запустіть DriveForge на комп'ютері з однією з цих редакцій.",
			["HiveBlockedDone"] = "Ці налаштування не вдалося записати в образ, бо цей ПК блокує доступ до офлайн-реєстру (майже завжди — антивірус): {0}.\n\nСам носій готовий і завантажиться — бракує лише цих налаштувань.",
			["Mb007"] = "Спочатку виберіть цільовий USB/SSD.",
			["BzWiping"] = "Очищення диска {0} ({1})...",
			["MbSurfaceTitle"] = "DriveForge — тест поверхні",
			["Mb008"] = "Вибраний диск позначено як системний/завантажувальний. DriveForge не форматуватиме його.",
			["BzCapacity"] = "Тестування реальної ємності {0}:...",
			["Mb025"] = "Це схоже на ISO Windows / WinPE.\n\nISO Windows не є «isohybrid», тому запис його як сирого образу зазвичай НЕ завантажується. Для правильного завантажувального USB Windows скористайтеся завданням \"[[SbCreateT]]\".\n\nВсе одно записати як сирий образ?",
			["Mb003"] = "Спочатку виберіть Windows ISO / WIM / ESD.",
			["BzVerify"] = "Перевірка диска {0}...",
			["MbTestBootTitle"] = "DriveForge — тест завантаження",
			["MbBackupCreated"] = "Резервний образ створено:\n\n{0}  ({1})\n\nЩоб відновити його пізніше: виберіть \"[[SbRestoreT]]\", виберіть цей .wim і вкажіть цільовий диск.",
			["MbFormatConfirm"] = "Відформатувати (стерти) цей диск?\n\n    Диск {0} — {1} — {2}\n\nЗараз цей диск містить:\n{3}\n\n⚠ УСЕ зазначене вище буде остаточно СТЕРТО.",
			["MbSchedDaily"] = "щодня",
			["MbBackupNoSpace"] = "Недостатньо вільного місця там, куди ви зберігаєте образ.\n\nОрієнтовно потрібно місця: ~{0}\nВільно на призначенні: {1}",
			["MbWriteIsoTitle"] = "DriveForge — запис ISO",
			["Mb014"] = "Паролі BitLocker мають містити щонайменше 8 символів (або залиште обидва порожніми, щоб використовувати лише ключ відновлення).",
			["BzShred"] = "Знищення файлів: {0}...",
			["Mb011"] = "Перезапустіть DriveForge від імені адміністратора, щоб створити резервний образ.",
			["Mb012"] = "Введіть дійсне ім’я облікового запису (без спеціальних символів).",
			["Mb039"] = "Спочатку виберіть диск для тестування.",
			["Mb036"] = "Перезапустіть DriveForge від імені адміністратора, щоб створити мультизавантажувальний USB.",
			["Mb006"] = "Зупинити поточну операцію? USB може бути незавершеним, і його доведеться форматувати знову.",
			["Mb033"] = "Спочатку виберіть дистрибутив зі списку.",
			["MbFormatTitle"] = "DriveForge — форматування диска",
			["Mb004"] = "Операція ще виконується. Закриття застосунку може залишити USB незавершеним. Ви впевнені, що хочете закрити?",
			["Mb009"] = "Спочатку виберіть вихідний образ.",
			["MbWipeFreeTitle"] = "DriveForge — очищення вільного простору",
			["Mb010"] = "Перезапустіть DriveForge від імені адміністратора, перш ніж створювати USB.",
			["MbDiskChanged"] = "Цільовий диск змінився від останнього сканування — можливо, тепер у цій позиції інший диск. Задля вашої безпеки операцію скасовано. Проскануйте диски ще раз і спробуйте знову.",
			["MbHyperVTitle"] = "DriveForge — потрібен Hyper-V",
			["BzWipeFree"] = "Очищення вільного простору на {0}:...",
			["Mb043"] = "Це системний диск — DriveForge не форматуватиме його.",
			["BzFormat"] = "Форматування диска {0} як {1}...",
			["Mb024"] = "Спочатку виберіть образ ISO.",
			["BzWriteIso"] = "Запис образу ISO на диск {0}...",
			["MbMultiBootSetup"] = "Налаштувати диск {0} як мультизавантажувальний USB?\n\n    {1} — {2}\n\nЗараз цей диск містить:\n{3}\n\n⚠ Диск буде СТЕРТО та налаштовано з мультизавантажувальним рушієм Ventoy. Після цього ви просто копіюєте на нього файли ISO (Windows, Linux, будь-що) і вибираєте один із меню під час завантаження.",
			["MbCloneHelperCreated"] = "Створено допоміжні файли для клонування поточного комп’ютера:\n\n{0}\n\nПовний клон неможливо створити, поки запущено цю Windows. Завантажтеся в \"Windows PE\", запустіть скрипт захоплення, а потім виберіть \"Restore a full computer clone\" у DriveForge.",
			["Mb029"] = "У вибраного диска немає літери. Спочатку скористайтеся Форматуванням, потім запустіть тест ємності.",
			["BzSurface"] = "Тест поверхні диска {0}...",
			["Mb005"] = "Зупинити поточну операцію? Поточний файл завершиться або не вдасться, а наступний запуск зможе продовжити з дійсних скопійованих файлів.",
			["ErrSchedTask"] = "Не вдалося створити заплановане завдання",
			["BzCleanVm"] = "Очищення тестової VM завантаження...",
