			["RecFilterLabel"] = "Фільтр", ["RecSelectAllButton"] = "Вибрати все", ["RecSelectNoneButton"] = "Зняти вибір", ["RecoverStopButton"] = "Стоп", ["RecoverDeepScanButton"] = "Глибоке сканування", ["CreateImageButton"] = "Створити образ диска…", ["OpenImageButton"] = "Відкрити образ…", ["CleanTab1Header"] = "Очищення слідів", ["CleanTab2Header"] = "Дисковий простір", ["AnalyzePanelDesc"] = "Дізнайтеся, що займає диск: проскануйте будь-яку папку чи диск, перегляньте карту розмірів вкладених папок, найбільші файли та дублікати, які можна безпечно видалити. Лише читання, доки ви не виберете видалити.", ["AnalyzeFolderLabel"] = "Папка для сканування", ["AnalyzeBrowseButton"] = "Огляд…", ["AnalyzeScanButton"] = "Сканувати", ["AnalyzeStopButton"] = "Стоп", ["AnalyzeBigFilesTab"] = "Найбільші файли", ["AnalyzeDupesTab"] = "Дублікати файлів", ["AnalyzeKeepFirstButton"] = "Вибрати дублікати (лишити 1)", ["AnalyzeDeleteButton"] = "Видалити вибране", ["AnalyzeNoFolder"] = "Спершу виберіть папку для сканування.", ["AnalyzeScanning"] = "Сканування… {0}", ["AnalyzeHashing"] = "Пошук дублікатів…", ["AnalyzeResult"] = "{0:N0} файлів · усього {1} · найбільша підпапка: {2}", ["AnalyzeDupResult"] = "· {0} груп дублікатів ({1} зайвих копій, {2} можна звільнити)", ["AnalyzeDeleteTitle"] = "Видалення файлів", ["AnalyzeDeleteDone"] = "Видалено файлів: {0} — {1}. Те, що потрапило до Кошика, не звільняє місця, доки ви його не спорожните.", ["PredReplace"] = "Скоро замінити", ["PredWatch"] = "Стежте за цим диском", ["PredHealthy"] = "Ознак відмови немає", ["PredUnknown"] = "Недостатньо даних SMART для прогнозу", ["PredReasonHealth"] = "повідомляє {0}", ["PredReasonUncorrected"] = "{0} невиправних помилок читання / {1} запису", ["PredReasonWear"] = "знос {0}%", ["PredReasonErrors"] = "зареєстровано помилок: {0}", ["PredReasonTemp"] = "перегрів ({0} °C)", ["RecoverZipButton"] = "Відновити в ZIP…", ["RecoverSaveSessionButton"] = "Зберегти сесію…", ["RecoverOpenSessionButton"] = "Відкрити сесію…", ["RecoverZipTitle"] = "Відновити вибрані файли в zip", ["SessionSaveTitle"] = "Зберегти сесію сканування", ["SessionOpenTitle"] = "Відкрити сесію сканування", ["SessionNothing"] = "Спершу виконайте сканування.", ["SessionSaved"] = "Сесію збережено — файлів: {0}.", ["SessionLoaded"] = "Сесію завантажено — файлів: {0} з {1}.", ["PreviewSelect"] = "Виберіть зображення або текстовий файл для перегляду.", ["PreviewNone"] = "Немає перегляду для цього типу файлу.", ["PreviewFail"] = "Не вдалося показати перегляд (пошкоджено, обрізано або не підтримується).", ["A11yHelp"] = "Довідка", ["A11ySearch"] = "Фільтрувати файли", ["A11yTypeFilter"] = "Фільтрувати за типом файлу", ["A11yTreemap"] = "Карта розмірів папок", ["LiveCompleted"] = "Завершено 100%", ["LiveStopped"] = "Зупинено", ["LiveSpeedTest"] = "Тест швидкості", ["LivePercent"] = "Тест швидкості {0}%", ["DescIsoWrite"] = "Виберіть будь-який завантажувальний ISO (Linux, BSD, аварійні інструменти тощо). DriveForge запише його на USB як необроблений образ диска, зробивши завантажувальним на BIOS + UEFI.", ["Step2IsoImage"] = "Образ ISO", ["Step2ImageFile"] = "Файл образу", ["TbPartition"] = "Розділ", ["MvPartOption"] = "Перемістити розділ", ["ToolGrpDiagnose"] = "Діагностика", ["ToolGrpMaintain"] = "Обслуговування", ["ToolGrpErase"] = "Очищення", ["MvGptVerifyFail"] = "DriveForge не зміг перевірити контрольні суми GPT цього диска, тому не ризикуватиме переміщенням — нічого не змінено. (GPT може бути пошкоджений або диск має незвичайне розмічення.)", ["MvTitle"] = "Перемістити розділ", ["MvNoParts"] = "У MBR цього диска розділів не знайдено.", ["MvPickPart"] = "Який розділ перемістити?", ["MvDirPrompt"] = "Перемістити розділ до початку чи до кінця диска?", ["MvLeft"] = "До початку диска", ["MvRight"] = "До кінця диска", ["MvAmountPrompt"] = "На скільки МБ перемістити розділ?", ["MvOutOfRange"] = "Таке переміщення вийде за край диска або за перший 1 МБ. Виберіть менше значення.", ["MvOverlap"] = "Таке переміщення перекриє інший розділ. Виберіть менше значення або інший напрямок.", ["MvConfirm"] = "Перемістити розділ #{0} ({1})?\n\n    Зі зміщення {2}\n    На зміщення {3}\n\n⚠ ЕКСПЕРИМЕНТАЛЬНО. Дані розділу фізично переміщуються, а таблиця розділів перезаписується.\n\n• Спершу створіть образ диска (Відновлення → Створити образ диска) на випадок проблем.\n• НЕ вимикайте й не від'єднуйте під час переміщення — його не можна безпечно перервати.\n\nПродовжити?", ["MvWorking"] = "Переміщення розділу — НЕ вимикайте…", ["MvDone"] = "Готово. Розділ #{0} переміщено. Якщо бракує літери диска, перевірте «Керування дисками».", ["MvStopIgnored"] = "Ви натиснули «Стоп», і це було навмисно проігноровано: переміщення розділу не можна безпечно перервати — на півдорозі розділ існує у двох місцях і не читається в жодному. Йому дали завершитися. Нічого не пошкоджено.", ["MvFailed"] = "Не вдалося перемістити розділ. Таблиця розділів залишилася без змін.", ["PtResize"] = "Змінити розмір розділу (збільшити / зменшити)", ["PtCreate"] = "Створити розділ (у вільному місці)", ["PtCreatePrompt"] = "Розмір нового розділу в МБ? (порожньо = усе нерозподілене місце)", ["PtCreateConfirm"] = "Створити новий розділ на Диску {0}, використовуючи нерозподілене місце?\n\nНаявні розділи не змінюються.", ["PtCreateDone"] = "Готово. На Диску {0} створено новий розділ.", ["PtCreateFailed"] = "Не вдалося створити розділ — можливо, на диску немає нерозподіленого місця. Див. деталі нижче.", ["PtDeleteFailed"] = "Том {0}: не видалено — Windows відмовив. Можливо, він використовується, або це захищений системний чи відновлювальний розділ. Подробиці нижче.", ["PtDelete"] = "Видалити розділ (звільнити місце)", ["PtDeleteConfirm"] = "Видалити том {0}: і перетворити його на нерозподілене місце?\n\n⚠ Усе на {0}: буде безповоротно видалено. Скасувати не можна.", ["PtDeleteDone"] = "Готово. Том {0}: видалено; його місце тепер нерозподілене.", ["PtResizePrompt"] = "Змінити розмір тому {0}: — збільшити чи зменшити?", ["PtGrow"] = "Збільшити (розширити у вільне місце після нього)", ["PtShrink"] = "Зменшити (звільнити місце в кінці)", ["PtShrinkPrompt"] = "Скільки МБ звільнити з {0}: ? (макс ≈ {1} МБ)", ["PtGrowPrompt"] = "Скільки МБ додати до {0}: ? (порожньо = усе вільне місце одразу після нього)", ["PtBadAmount"] = "Введіть ціле число мегабайтів.", ["PtShrinkConfirm"] = "Зменшити {0}: на {1} МБ?\n\nЗвільнене місце стане нерозподіленим. Ваші файли збережено.", ["PtGrowConfirm"] = "Збільшити {0}: за рахунок нерозподіленого місця після нього?", ["PtResizeWorking"] = "Зміна розміру {0}: …", ["PtResizeDone"] = "Готово. Розмір тому {0}: змінено.", ["PtResizeFailed"] = "diskpart не зміг змінити розмір тому — див. деталі нижче (напр., немає вільного місця одразу після нього або обмежено нерухомими файлами).", ["PtNoDisk"] = "Спочатку виберіть диск (Диск для перевірки).", ["PtSystemBlocked"] = "Це системний диск — DriveForge не змінює його розділи.", ["PtTitle"] = "Інструменти розділів", ["PtPrompt"] = "Виберіть дію для Диска {0}:", ["PtQuickPart"] = "Швидке розбиття (стерти та створити заново)", ["PtInit"] = "Ініціалізувати порожній / RAW-диск", ["PtConvert"] = "Перетворити MBR ↔ GPT (стирає диск)", ["PtCheck"] = "Перевірити файлову систему (CHKDSK)", ["PtActive"] = "Зробити перший розділ активним (прапор завантаження MBR)", ["PtFindLost"] = "Знайти втрачені розділи (сканування лише для читання)", ["PtConfirmBody"] = "{0} на цьому диску?\n\n    Диск {1} — {2} — {3}\n\nЗараз містить:\n{4}\n\n⚠ Усе буде СТЕРТО. Скасувати не можна.", ["PtWorking"] = "{0} на вибраному диску…", ["PtCountPrompt"] = "Скільки розділів створити на Диску {0}?", ["PtFsPrompt"] = "Виберіть файлову систему для нових розділів:", ["PtQuickDone"] = "Готово. Диск {0} тепер має {1} × {2} розділ(ів).", ["PtInitPrompt"] = "З яким стилем розділів ініціалізувати Диск {0}?", ["PtGpt"] = "GPT (сучасний, >2 ТБ, UEFI)", ["PtMbr"] = "MBR (застарілий, BIOS)", ["PtInitDone"] = "Готово. Диск {0} ініціалізовано та відформатовано (NTFS).", ["PtConvertDone"] = "Готово. Диск {0} тепер {1}.", ["PtNoVolumes"] = "Цей диск не має відформатованих томів.",["PtGrowNoRoom"] = "{0}: не може збільшитися — одразу за ним немає нерозміченого місця.\n\nРозділ може рости лише в те вільне місце, яке йде одразу за ним. Місце перед ним або за іншим розділом не підійде: спочатку видаліть або перемістіть те, що між ними.", ["PtPickVolume"] = "Який том перевірити?", ["PtChecking"] = "Перевірка {0}: …", ["PtCheckDone"] = "Перевірка {0}: завершена.", ["PtActiveGpt"] = "На GPT-диску немає прапора 'активний' — UEFI завантажується із системного розділу EFI.", ["PtActiveConfirm"] = "Зробити перший розділ Диска {0} активним (завантажувальним)?", ["PtActiveDone"] = "Готово. Перший розділ Диска {0} тепер активний.", ["PtActiveNotSet"] = "Диск {0}: перший розділ досі не позначено як активний. diskpart не повідомив про помилку, але прапорець не змінився — можливо, на диску немає розділу 1, або Windows відмовив. Подробиці нижче.", ["PtQuickPartial"] = "Диск {0} вийшов не таким, як просили: на ньому {1} розділ(ів) із {2} запитаних, і Windows повідомляє на ньому такі файлові системи: {3}. diskpart зупинився на півдорозі, не повідомивши про помилку. Подробиці нижче.", ["MbFormatNoFs"] = "Диск {0} розбито на розділи, але Windows не повідомляє на ньому файлової системи {1} — форматування не завершилося, хоча diskpart не повідомив про помилку. Носій поки не готовий до використання. Подробиці нижче; спробуйте ще раз або відформатуйте його в «Керуванні дисками».", ["PtScanningLost"] = "Сканування Диска {0} на втрачені розділи…", ["PtLostNone"] = "Сигнатури розділів на Диску {0} не знайдено.", ["PtLostUnmounted"] = "не змонтований (можливо, втрачений)", ["PtLostFound"] = "Знайдено розділів: {0} на Диску {1}:", ["PtLostHint"] = "Сканування лише для читання — нічого не змінено. Щоб відновити втрачений розділ, скористайтеся спеціалізованим інструментом для відновлення розділів; щоб врятувати його файли, створіть образ диска та відновіть дані з образу.",["PtLostStopped"] = "\n\nСканування не завершено, тож це лише те, до чого воно дійшло - решта диска не перевірялася.", ["WipeSsd"] = "Очищення SSD (TRIM — придатне очищення для SSD)", ["SsdConfirm"] = "Очистити SSD Диск {0}?\n\n    {1} — {2}\n\nЗараз містить:\n{3}\n\n⚠ Усі дані буде відкинуто. Скасувати не можна.", ["SsdWorking"] = "Очищення Диска {0} (швидке форматування + TRIM)…", ["SsdDone"] = "Готово. Диск {0} очищено та стерто через TRIM — на SSD контролер відкидає старі блоки даних. Для сертифікованого очищення запустіть також фірмовий інструмент Secure Erase.", ["RecPreviewLabel"] = "Перегляд", ["EjectDriveButton"] = "Безпечно вилучити", ["AddAllDriversCheck"] = "Додати ВСІ драйвери цього ПК (повільніше)", ["AddNetworkDriversCheck"] = "Додати мережеві / Wi-Fi драйвери цього ПК", ["EjectWhenDoneCheck"] = "Вилучити диск після завершення", ["UseDismEngineCheck"] = "Використовувати рушій Microsoft (DISM)", ["UseNtfsRawEngineCheck"] = "Швидке клонування", ["OpenReportButton"] = "Відкрити останній звіт", ["ScheduleCloneButton"] = "Запланувати це клонування (автоматичне резервування)…", ["StartBackup"] = "Резервна копія у файл образу", ["SbCleanT"] = "Очищення слідів", ["SbCleanS"] = "Звільніть місце та зітріть сліди використання", ["CleanPanelTitle"] = "Очищення слідів", ["CleanPanelDesc"] = "Звільніть місце на диску та видаліть сліди використання, залишені Windows і вашими програмами. Позначте, що очистити, натисніть «Аналіз», щоб побачити обсяг, потім «Очистити». Ніщо ніколи не залишає ваш ПК.", ["ChkCleanTemp"] = "Тимчасові файли (Windows + програми)", ["ChkCleanRecent"] = "Останні файли та списки переходів", ["ChkCleanThumbs"] = "Кеш ескізів", ["ChkCleanBrowser"] = "Кеш браузерів (Edge, Chrome, Firefox)", ["ChkCleanPrefetch"] = "Windows Prefetch", ["ChkCleanUpdate"] = "Кеш Windows Update", ["ChkCleanRecycle"] = "Кошик (усі диски)", ["ChkCleanDns"] = "Кеш DNS", ["ChkCleanClipboard"] = "Вміст буфера обміну", ["CleanAnalyzeButton"] = "Аналіз", ["CleanRunButton"] = "Очистити", ["CleanSelectAllButton"] = "Вибрати все", ["CleanNote"] = "Безпечно за задумом: очищуються лише стандартні розташування кешу й тимчасових файлів, а використовувані файли пропускаються. Очищення Кошика остаточно видаляє його вміст. Деякі пункти (Prefetch, кеш Windows Update) потребують прав адміністратора.", ["CleanAnalyzing"] = "Аналіз…", ["CleanAnalyzeResult"] = "Можна звільнити близько {0}.", ["CleanAnalyzeAdvanced"] = "Ще {0} міститься в додаткових пунктах - позначте [[CleanAdvancedToggle]], щоб їх охопити.", ["BzCleaning"] = "Триває очищення...", ["CleanNothingSelected"] = "Нічого не вибрано.", ["CleanConfirmTitle"] = "Очищення слідів", ["CleanConfirmBody"] = "Це безповоротно видалить вибрані елементи:", ["CleanCleaningX"] = "Очищення: {0}…", ["CleanDone"] = "Готово — звільнено {0} (видалено файлів: {1}).", ["CleanStopped"] = "Зупинено — звільнено {0} (видалено файлів: {1}). Не очищено позначених пунктів: {2}.", ["RecTypeAll"] = "Усі", ["RecTypePictures"] = "Зображення", ["RecTypeDocuments"] = "Документи", ["RecTypeAudio"] = "Аудіо", ["RecTypeVideo"] = "Відео", ["RecTypeArchives"] = "Архіви",
