			["ErrInit"] = "इनिशियलाइज़ विफल", ["ErrMbrTooBig"] = "इस इमेज में MBR योजना के पते में आने वाले लगभग 2 TB से ज़्यादा है, इसलिए इसे इस ड्राइव पर बहाल नहीं किया जा सकता। कुछ भी नहीं बदला गया - ड्राइव फ़ॉर्मैट नहीं हुई।", ["ErrImageBadCheck"] = "बैकअप इमेज अखंडता जाँच में पास नहीं हुई, इसलिए वह ख़राब या अधूरी हो सकती है। लक्ष्य ड्राइव फ़ॉर्मैट नहीं की गई।", ["ErrImageNoWindows"] = "इस इमेज में Windows की स्थापना नहीं है (इसके Windows पार्टीशन पर SYSTEM रजिस्ट्री हाइव नहीं है)। लक्ष्य पर कुछ नहीं लिखा गया।", ["ErrFfuExtension"] = "पूरा क्लोन बहाल करने के लिए .ffu एक्सटेंशन वाली क्लोन फ़ाइल चाहिए।", ["ErrNoDiskInfo"] = "Windows ने कोई डिस्क जानकारी नहीं लौटाई। हो सकता है Get-Disk उपलब्ध न हो (StorageWMI घटक के बिना वाला WinPE बिल्ड) या Virtual Disk सेवा चल न रही हो।", ["ErrIsoMountFailed"] = "Windows इस ISO फ़ाइल को माउंट नहीं कर सका। वह ख़राब हो सकती है, या अभी किसी दूसरे प्रोग्राम के इस्तेमाल में हो सकती है।", ["ErrNoInstallImage"] = "इस ISO में न sources\\install.wim है और न sources\\install.esd, इसलिए यह Windows स्थापना इमेज नहीं है।", ["ErrNoDriveLetters"] = "कोई ख़ाली ड्राइव अक्षर नहीं बचा। किसी ड्राइव को हटाएँ या अनमाउंट करें और दोबारा कोशिश करें।", ["ErrDownloadIncomplete"] = "डाउनलोड समय से पहले रुक गया: {1} में से {0} आया। फ़ाइल सहेजी नहीं गई।", ["ErrRawEngineMft"] = "इस वॉल्यूम की मुख्य फ़ाइल तालिका एक अतिरिक्त एट्रिब्यूट सूची में बँटी है, जिसे रॉ इंजन नहीं पढ़ता - वह चुपचाप फ़ाइलें छोड़ देगा। रॉ इंजन बंद करें और इस वॉल्यूम के लिए मानक इंजन इस्तेमाल करें।", ["ErrRawEngineNotNtfs"] = "स्नैपशॉट वॉल्यूम NTFS नहीं है, और रॉ इंजन सिर्फ़ NTFS वाले Windows वॉल्यूम क्लोन करता है। इस वॉल्यूम के लिए रॉ इंजन बंद करें।", ["ErrBootSector"] = "{0} का बूट सेक्टर पढ़ा नहीं जा सका, इसलिए इस फ़ाइल सिस्टम की जाँच नहीं हो सकती।", ["ErrSessionBad"] = "यह सत्र फ़ाइल ख़ाली है या DriveForge का स्कैन सत्र नहीं है।", ["ErrSessionNewer"] = "यह स्कैन सत्र किसी नए DriveForge ने सहेजा था (फ़ॉर्मैट v{0})। इसे खोलने के लिए DriveForge अपडेट करें।", ["ErrWrongDiskRecover"] = "ड्राइव {0}: वह