			["StgRestoreFullClone"] = "Memulihkan klon komputer lengkap...",
			["StgVerifyRestoredClone"] = "Memverifikasi klon yang dipulihkan...",
			["MbCloneDoneOk"] = "Klon setia selesai.\n\nPemeriksaan yang diperlukan lolos.",
			["MbCloneDoneReview"] = "Klon setia selesai, tetapi beberapa pemeriksaan perlu ditinjau.",
			["MbCloneBody"] = "Disk yang dipilih telah diformat. DriveForge mengkloning seluruh root Windows saat ini dengan setia (penerapan image WIM), mempertahankan aplikasi, ACL, dan status AppX.",
			["MbCloneBitlockerBusy"] = "BitLocker MASIH MENGENKRIPSI di latar belakang — biarkan drive tetap terhubung hingga 'manage-bde -status' menunjukkan 100%.",
			["MbCloneSafeRemove"] = "Drive telah di-flush dan aman untuk dilepas.",
			["MbCloneBootHelp"] = "Cara menjalankannya: colokkan ke PC target, nyalakan, buka menu boot (F12 / F9 / Esc / F2 tepat setelah dinyalakan) dan pilih drive ini. Boot pertama memakan beberapa menit.",
			["MbCloneReportLabel"] = "Laporan:",
			["MbCloneDataFail"] = "CATATAN: {0} dari {1} partisi data tambahan GAGAL dikloning (lihat laporan/log). Partisi Windows lengkap, tetapi drive data tersebut hilang atau sebagian pada klon.",
			["SaveLogButton"] = "Simpan log",
			["FltExportVhdx"] = "Image yang dapat di-boot — Hyper-V atau pulihkan ke drive (*.vhdx)|*.vhdx|Image yang dapat di-boot — VirtualBox/QEMU atau pulihkan ke drive (*.vhd)|*.vhd|Image disk — VMware (*.vmdk)|*.vmdk",
			["FltRestoreImage"] = "Image cadangan/klon (*.wim;*.vhdx;*.vhd;*.ffu)|*.wim;*.vhdx;*.vhd;*.ffu|Cadangan WIM (*.wim)|*.wim|Image VHDX (*.vhdx;*.vhd)|*.vhdx;*.vhd|Klon penuh (*.ffu)|*.ffu|Semua file (*.*)|*.*",
			["FltInstallImage"] = "Image Windows (*.iso;*.wim;*.esd)|*.iso;*.wim;*.esd|Image ISO (*.iso)|*.iso|Image WIM (*.wim)|*.wim|Image ESD (*.esd)|*.esd|Semua file (*.*)|*.*", ["FltRawDiskImage"] = "Image disk (*.iso;*.img;*.bin;*.raw;*.dd)|*.iso;*.img;*.bin;*.raw;*.dd|Image ISO (*.iso)|*.iso|Image disk mentah (*.img;*.bin;*.raw;*.dd)|*.img;*.bin;*.raw;*.dd|Semua berkas (*.*)|*.*",
			["MbAvCloneNote"] = "Jika Anda memakai antivirus pihak ketiga (mis. Bitdefender, Kaspersky), mungkin perlu diinstal ulang atau diperbaiki di drive ini — perangkat lunak keamanan terikat ke perangkat keras dan sering tidak mau berjalan setelah kloning. Windows Defender tidak terpengaruh.",
			["DescBackupVhdxHint"] = "Ringkas dan mendukung cadangan inkremental — terbaik untuk cadangan berulang. Tips: antivirus pihak ketiga bisa mengunci file saat cadangan .wim; untuk image 100% setia dan dapat di-boot yang kebal terhadap antivirus, gunakan '[[TbExportVhdx]]'.",
			["ExportVhdxBackupHint"] = "Salinan 100% setia dan dapat di-boot dari PC ini — kebal antivirus. Anda bisa memulihkannya ke drive nanti dengan '[[SbRestoreT]]', atau menjalankannya di VM Hyper-V. Untuk cadangan yang lebih kecil, terkompresi, dan inkremental, gunakan '[[SbBackupT]]'.", ["ExPanelNote"] = "Membuat berkas .vhdx yang dapat di-boot dari snapshot hanya-baca (mesin Kloning cepat, tidak terlihat oleh antivirus) untuk mesin virtual Hyper-V Generasi 2 / UEFI. PC Anda tidak diubah. Tips: mengekspor dari disk internal jauh lebih cepat daripada dari drive USB.",
			["MbBackupReadFail"] = "Cadangan tidak dapat membaca salah satu file, sehingga image TIDAK LENGKAP dan telah dibuang.\n\nIni hampir selalu file terenkripsi (EFS), atau file yang dikunci secara eksklusif oleh program lain. Tutup program yang mungkin membuka file dan coba lagi.\n\nJika terus gagal pada file yang sama, file itu kemungkinan terenkripsi EFS dan tidak dapat ditangkap ke .wim dengan cara ini.",
			["MbAvWarnTitle"] = "Antivirus dapat memperlambat kloning",
			["MbSrcOnTarget"] = "File yang Anda tulis tersimpan DI drive yang akan Anda hapus — ini akan menghancurkan file sumbernya sendiri. Pindahkan dulu ke drive lain.",
			["MbAvOfferDism"] = "{0} tampaknya aktif. Ia memindai setiap file yang dibaca mesin kloning standar, yang dapat membuat kloning sangat lambat (sering terlihat macet di sekitar WinSxS).\n\nDriveForge dapat mengkloning dengan mesin milik Microsoft (DISM) — antivirus tidak memperlambatnya, dan Anda tidak perlu mengubah apa pun di antivirus Anda.\n\n  •  Ya  —  gunakan mesin Microsoft (disarankan, cepat)\n  •  Tidak  —  tetap gunakan mesin standar (bisa sangat lambat)\n  •  Batal  —  hentikan\n\nGunakan mesin Microsoft?",
			["PtTooSmall"] = "Disk ini terlalu kecil untuk dibagi menjadi {0} partisi. Pilih partisi lebih sedikit.",
			["MbExportVhdxEfsWarn"] = "\n\n⚠ {0} berkas terenkripsi EFS tidak disalin — hilang dari VHDX.",
			["SbExportVhdxS"] = "Jalankan PC ini di mesin virtual Hyper-V",
			["TbExportVhdx"] = "Ekspor VHDX",
			["BzExportVhdx"] = "Mengekspor ke VHDX yang dapat di-boot…",
			["ErrExportVhdx"] = "Tidak dapat mengekspor VHDX",
			["MbExportVhdxConfirm"] = "Buat image VHDX yang dapat di-boot dari Windows PC ini?\n\nDriveForge menyalin snapshot Windows yang sedang berjalan ke file .vhdx baru — PC Anda tidak diubah. Anda bisa mem-boot-nya di VM Hyper-V Generasi 2 (UEFI), atau memulihkannya ke drive fisik nanti dengan '[[SbRestoreT]]'. Ini memakan beberapa menit.\n\nLanjutkan?",
			["MbExportVhdxDone"] = "VHDX yang dapat di-boot siap:\n{0}\n\nDi Hyper-V, buat VM Generasi 2, lampirkan VHDX ini sebagai disk boot, dan MATIKAN Secure Boot di pengaturan keamanan mesin.",
			["MbExportVhdxVmOffer"] = "VHDX yang dapat di-boot sudah siap:\n{0}\n\nBuat dan jalankan mesin virtual Hyper-V Generasi 2 dari file ini sekarang?",
