			["Mb030"] = "لا توجد مساحة حرة كافية للاختبار. أفرغ محرك الأقراص أو قم بتهيئته أولاً.",
			["MbWipeConfirm"] = "مسح (محو) محرك الأقراص هذا بشكل آمن؟\n\n    القرص {0} — {1} — {2}\n\nيحتوي هذا القرص حالياً على:\n{3}\n\n⚠ سيُكتب فوق كل قطاع. لن تكون البيانات قابلة للاسترداد. لا يمكن التراجع عن هذا.", ["MbWipeConfirmQuick"] = "مسح جدول الأقسام على محرك الأقراص هذا؟\n\n    القرص {0} — {1} — {2}\n\nيحتوي هذا القرص حالياً على:\n{3}\n\n⚠ اخترت الطريقة السريعة، لذا لن يُكتب فوق أي شيء. تبقى الملفات موجودة فعلياً على القرص ويمكن استردادها ببرامج الاسترداد. اختر إحدى طرق الكتابة فوق البيانات إذا أردت إزالتها نهائياً.",
			["MbShredConfirm"] = "تمزيق {0} من الملفات نهائياً؟\n\nسيُكتب فوق محتويات كل ملف ({1} تمريرة) ثم يُحذف. لا يمكن التراجع عن هذا.\n\n(ملاحظة: في أقراص SSD/USB الفلاش، يعني توزيع التآكل أن بعض النسخ قد تبقى فعلياً؛ للتأكد التام في الفلاش، نفّذ أيضاً مسحاً كاملاً للمحرك أو استخدم المسح الآمن للمحرك.)",
			["DkNoLetter"] = "بدون حرف",			["DkSystemDisk"] = "يعمل عليه WINDOWS (لا تهيئة/مسح)",			["DkHealthOk"] = "الحالة: OK",			["DkHealth"] = "الحالة: {0}",
			["DkRow"] = "القرص {0}",
			["DkInternalDisk"] = "قرص داخلي — ليس محرك أقراص قابلاً للإزالة",
			["MbConfirmSummary"] = "{0}\n\n    {1} — {2} — {3}\n\nيحتوي هذا القرص حالياً على:\n{4}\n\n⚠ سيُمحى كل ما سبق.\n\n{5}\n\nالوقت المقدَّر: {6}.{7}\n\nهل تريد المتابعة؟",			["CoActClone"] = "استنساخ Windows هذا الحاسوب إلى:",			["CoActRestore"] = "استعادة صورة قرص محفوظة إلى:",			["CoActCreate"] = "إنشاء USB لـ Windows على:",			["CoOptions"] = "الخيارات: {0}.",			["CoOptionsNone"] = "الخيارات: الافتراضية.",			["CoOptBitLocker"] = "التشفير بـ BitLocker (يُحفظ مفتاح الاسترداد)",			["CoOptLocalAcct"] = "تخطّي حساب Microsoft (إنشاء حساب محلي)",			["CoOptBypassReq"] = "تجاوز متطلبات Windows 11",			["CoOptWholeDisk"] = "استنساخ القرص بالكامل (Windows + جميع أقسام البيانات)",			["CoOptOtherParts"] = "استنساخ أقسام البيانات الأخرى أيضاً",			["CoOptDataPart"] = "إنشاء قسم بيانات إضافي",			["CoOptVerify"] = "التحقق من البيانات المستنسخة بعد الانتهاء",			["CoOptCompact"] = "صورة مضغوطة (توفّر المساحة)",			["CoSlowNote"] = "\n\nملاحظة: قد يكون هذا المحرك بطيئاً لـ Windows To Go.",			["CoTitle"] = "تأكيد — يُرجى المراجعة",			["EstMinute"] = "دقيقة تقريباً",			["EstMinutes"] = "{0} دقيقة تقريباً",			["EstHours"] = "{0} ساعة تقريباً", ["EstFromBurst"] = "، بالسرعة المقيسة على 80 MB — والكتابة الطويلة أبطأ في الغالب", ["EstNoTest"] = "، بسرعة قرص اعتيادية — ولم يُجرَ اختبار السرعة على هذا القرص",
			["MbShredWhat"] = "سيتم التمزيق، من هذا المجلد:\n{0}\n\n{1} في {2} ملف(ات)، على سبيل المثال:\n{3}\n\n",
			["MbSchedWeekly"] = "كل أحد",
			["Mb037"] = "أدخل محرك USB الذي تريد استخدامه، ثم حاول مرة أخرى.",
			["Mb040"] = "أعد تشغيل DriveForge كمسؤول لتشغيل اختبار السطح.",
			["Mb034"] = "تعذّر العثور على رابط تنزيل حالي تلقائياً. استخدم زر صفحة التنزيل الرسمية بدلاً من ذلك.",
			["MbFormatDone"] = "تم. تمت تهيئة القرص {0} كـ {1} وأصبح جاهزاً للاستخدام.",
			["Mb031"] = "هذا قرص نظام — لن يُجري DriveForge اختبار الإقلاع عليه.",
			["MbBootHelp"] = "\n\nكيفية بدء التشغيل منه: صِل محرك الأقراص بالكمبيوتر الهدف، وشغّله، وافتح قائمة الإقلاع (عادةً F12 أو F9 أو Esc أو F2 مباشرة بعد التشغيل)، ثم اختر جهاز USB/SSD هذا. يستغرق الإقلاع الأول بضع دقائق بينما يقوم Windows بإعداد برامج التشغيل.",
			["MbBitLockerNote"] = "\n\nملاحظة: لا يزال BitLocker يقوم بالتشفير في الخلفية — أبقِ محرك الأقراص متصلاً حتى يصل إلى 100% (manage-bde -status)، أو سينتهي عند أول إقلاع للنسخة المستنسخة.",
			["MbReinstallConfirm"] = "ستؤدي إعادة التثبيت إلى محو جميع الملفات (بما في ذلك صور ISO الخاصة بك) على القرص {0}. متابعة؟",
			["Mb028"] = "لن يُجري DriveForge اختبار السعة على قرص نظام.",
			["Mb042"] = "حدد محرك الأقراص المراد تهيئته أولاً ([[DiagDriveToTestLabel]]).",
			["Mb027"] = "حدد محرك الأقراص المراد اختباره أولاً ([[DiagDriveToTestLabel]]).",
			["Mb045"] = "أعد تشغيل DriveForge كمسؤول لإدارة الأقسام.",
			["Mb022"] = "أعد تشغيل DriveForge كمسؤول لمسح محركات الأقراص.",
			["MbMultiBootDone"] = "تم! أصبح القرص {0} الآن USB متعدد الإقلاع.\n\nانسخ ملفات ISO الخاصة بك إلى محرك \"Ventoy\" الذي فُتح للتو — أضف ما يتسع منها (Windows أو Linux أو أدوات الإنقاذ).\n\nأقلِع أي كمبيوتر من محرك الأقراص هذا واختر صورة ISO من القائمة. نصيحة: استخدم [[TbTestBoot]] للتحقق من أنه يُقلع.",
			["Mb021"] = "هذا قرص نظام — لن يقوم DriveForge بمسحه.",
			["MbIsoTooBig"] = "صورة ISO ({0}) أكبر من محرك الأقراص ({1}).",
			["Mb018"] = "هذا قرص نظام — لا يمكن إخراجه.",
			["Mb015"] = "لا يتوفر أي تقرير بعد.",
			["Mb016"] = "لا يحتوي محرك الأقراص هذا على حرف محرك أقراص. قم بتهيئته أولاً، ثم امسح مساحته الحرة.",
			["Mb013"] = "كلمتا المرور غير متطابقتين.",
			["MbNoFreeWipe"] = "لا توجد مساحة حرة تقريباً لمسحها على {0}:.",
			["MbSchedCreated"] = "تم إنشاء المهمة المجدولة \"DriveForge Auto Clone\".\n\nستقوم باستنساخ هذا الكمبيوتر إلى '{0}' {1} في الساعة 02:00، طالما أن محرك الأقراص هذا متصل.\n\nأزِلها في أي وقت من Task Scheduler في Windows (أو سيُستبدل إذا قمت بالجدولة مرة أخرى).",
			["MbWipeFreeConfirm"] = "مسح المساحة الحرة على {0}:؟\n\nلن تُمَس ملفاتك الحالية. يملأ DriveForge مساحة {1} الحرة ببيانات الكتابة فوقها ({2} تمريرة) ثم يزيلها، بحيث لم يعد بالإمكان استرداد الملفات التي حذفتها سابقاً.\n\nسيكون محرك الأقراص ممتلئاً مؤقتاً أثناء العملية. متابعة؟",
			["Mb038"] = "يعمل الإقلاع المتعدد بواسطة محرك Ventoy المجاني مفتوح المصدر (GPL-3.0). يحتاج DriveForge إلى تنزيله مرة واحدة (~16 MB)؛ ثم يُخزّن مؤقتاً للاستخدام دون اتصال.\n\nتنزيله الآن؟",
			["Mb035"] = "الصق رابط http(s) مباشراً إلى ملف ISO.",
			["Mb032"] = "أعد تشغيل DriveForge كمسؤول لتشغيل اختبار الإقلاع.",
			["Mb020"] = "حدد محرك الأقراص المراد مسحه أولاً ([[DiagDriveToTestLabel]]).",
			["MbBootTestOfflineWarn"] = "انتهى اختبار الإقلاع، لكن إعادة القرص {0} إلى وضع الاتصال ربما فشلت.\n\nإذا كان محرك الأقراص مفقوداً من Explorer، فأعد تفعيله في Disk Management، أو شغّل في PowerShell بصلاحيات المسؤول:\n    Set-Disk -Number {0} -IsOffline $false",
			["MbWriteIsoConfirm"] = "كتابة صورة ISO هذه إلى USB كصورة إقلاعية؟\n\n    ISO: {0} ({1})\n    إلى: القرص {2} — {3} — {4}\n\nيحتوي هذا القرص حالياً على:\n{5}\n\n⚠ سيُمحى كل شيء على القرص. (يعمل مع Linux وصور isohybrid الأخرى؛ من الأفضل إنشاء صورة Windows ISO باستخدام \"[[SbCreateT]]\".)",
			["Mb041"] = "لم يتم تحديد أي شيء.",
			["MbHyperV"] = "يحتاج اختبار الإقلاع إلى ميزة Hyper-V، وهي غير مفعّلة على هذا الكمبيوتر.\n\nفتح \"Turn Windows features on or off\" لتتمكن من تفعيل Hyper-V؟ (يلزم إعادة التشغيل بعد تفعيلها.)",
			["Mb044"] = "أعد تشغيل DriveForge كمسؤول لتهيئة محركات الأقراص.",
			["MbBootTestConfirm"] = "اختبار إقلاع محرك الأقراص هذا في جهاز ظاهري؟\n\n    القرص {0} — {1} — {2}\n\nسيقوم DriveForge بما يلي:\n• نقل هذا القرص إلى وضع عدم الاتصال (حتى يتمكن VM من استخدامه)،\n• بدء تشغيل VM مؤقت بنظام {3} يُقلع منه،\n• فتح نافذة لتتمكن من مشاهدة إقلاعه.\n\nراقب فقط أنه يصل إلى قائمة الإقلاع / الشعار — لا تشغّل أداة تثبيت داخل VM. عند الانتهاء، عُد إلى هنا وانقر OK لإيقاف الاختبار وإعادة القرص إلى وضع الاتصال.",
			["Mb019"] = "تم تفريغ محرك الأقراص وإخراجه.\n\nإذا كان Windows لا يزال يعرضه، فانتظر لحظة ثم افصله. (قد لا تُخرَج أقراص SATA/NVMe الداخلية — وهذا أمر طبيعي.)",
			["MbSurfaceConfirm"] = "تشغيل اختبار سطح للقراءة فقط على:\n    القرص {0} — {1} — {2}\n\nيقرأ DriveForge كل قطاع للعثور على الكتل التالفة/غير القابلة للقراءة. لا تُكتب أي بيانات. قد تستغرق محركات الأقراص الكبيرة بعض الوقت — استخدم Stop للإلغاء.",
			["MbVmRunning"] = "يعمل VM الخاص باختبار الإقلاع وقد فُتحت نافذته.\n\n• إذا رأيت شعار / قائمة إقلاع محرك الأقراص، فهو يُقلع بشكل صحيح. ✓\n• تعني الشاشة السوداء أو \"no bootable device\" أنه لا يُقلع — جرّب وضع البرنامج الثابت الآخر (UEFI ↔ Legacy BIOS).\n\nانقر OK عند الانتهاء لإيقاف الاختبار وإعادة القرص إلى وضع الاتصال.",
			["MbMultiBootTitle"] = "DriveForge — USB متعدد الإقلاع",
			["Mb017"] = "حدد محرك الأقراص المراد إزالته أولاً.",
			["MbShredTitle"] = "DriveForge — تمزيق آمن", ["MbShredDone"] = "تم. تم محو {0} ملفًا بأمان.", ["MbShredStopped"] = "تم الإيقاف. تم إتلاف {0} ملفًا حتى الآن.", ["MbShredNoReach"] = "\n\n⚠  تم حذف {0} ملفًا دون الكتابة فوقها. هذه الملفات مضغوطة أو متفرقة أو مشفّرة، ويكتبها Windows في مجموعات جديدة بدلاً من الكتابة فوق القديمة، لذا قد تظل البيانات الأصلية قابلة للاستعادة.", ["MbShredFailed"] = "\n\nتعذّر محو {0} ملفًا (قيد الاستخدام أو محمية).", ["MbShredLinks"] = "\n\n⚠ تم تخطي {0} عنصرًا لأنها اختصارات (روابط رمزية) إلى ملفات في مكان آخر. الكتابة فوقها كانت ستدمّر الملف الذي تشير إليه، وقد يكون على قرص آخر. امحُ تلك الملفات في موضعها الفعلي.",
			["MbCapacityTitle"] = "DriveForge — اختبار السعة",
			["MbCapacityConfirm"] = "التحقق من السعة الفعلية لـ:\n    {0} ({1}:) — يدّعي {2}\n\nيكتب هذا ~{3} من بيانات الاختبار إلى المساحة الحرة، ويقرأها مرة أخرى للتحقق، ثم يحذفها. لن تُمَس ملفاتك الحالية. للحصول على فحص كامل، شغّله على محرك أقراص فارغ.\n\nمتابعة؟",
			["MbDownloaded"] = "تم التنزيل:\n    {0}",
			["Mb001"] = "حدد محرك الأقراص الهدف أولاً.",
			["Mb002"] = "تعذّر تحديد مسار التطبيق لجدولته.",
			["BzBootVm"] = "جارٍ بدء تشغيل VM لاختبار إقلاع القرص {0}...",
			["MbUsbDone"] = "اكتمل إنشاء USB.",
			["MbRestoreDone"] = "اكتملت الاستعادة.",
			["HiveStepPortable"] = "إعدادات Windows المحمول",
			["BcdbootFailed"] = "لم يكتب Windows ملفات الإقلاع، لذلك لن يعمل هذا القرص. تم نسخ كل شيء آخر، لكن بدون سجل الإقلاع لا يمكن للقرص أن يقلع.",
			["BcdStoreCollision"] = "تعذّر إنشاء سجل الإقلاع لأن هذا الجهاز يرفض تحميله — وهو نفس الحظر الذي يمنع DriveForge من فتح السجل داخل صورة النظام، وغالبًا ما يكون مكافح فيروسات أو حزمة حماية. أوقف تلك الحماية لبضع دقائق ثم أعد المحاولة: لا عيب في القرص ولا في الصورة.",
			["HiveBlockedWarn"] = "⚠ هذا الجهاز لا يسمح لـ DriveForge بفتح السجل داخل صورة نظام — والسبب غالبًا برنامج مكافحة فيروسات أو حزمة حماية.\n\nاستنساخ هذا الجهاز سيتوقف في منتصف الطريق. أما قرص Windows على USB فسيُنشأ وسيقلع، لكن الإعدادات التي تُكتب في الصورة بعد ذلك (إعدادات Windows المحمول، تجاوز متطلبات Windows 11، تجاوز حساب Microsoft، إزالة البرامج الزائدة) ستكون مفقودة.\n\nعادةً يكفي إيقاف تلك الحماية لبضع دقائق.",
			["BitLockerEditionWarn"] = "⚠ هذا الإصدار من Windows لا يمكنه تشغيل BitLocker. إدارة BitLocker موجودة فقط في Windows Pro وEnterprise وEducation — أما Home فيرفضها بالخطأ 0x8031005A.\n\nكل شيء آخر سيُنفّذ تمامًا كما هو موضح وسيعمل القرص. لكنه ببساطة لن يكون مشفرًا، ولن يُنشأ أي مفتاح استرداد.\n\nأزل علامة خيار BitLocker لإخفاء هذا التحذير، أو شغّل DriveForge من جهاز يعمل بأحد تلك الإصدارات.",
			["HiveBlockedDone"] = "تعذّرت كتابة هذه الإعدادات في الصورة لأن هذا الجهاز يحجب الوصول إلى سجل غير متصل (غالبًا مكافح الفيروسات): {0}.\n\nالقرص نفسه جاهز وسيقلع — الناقص فقط هو تلك الإعدادات.",
			["Mb007"] = "حدد جهاز USB/SSD الهدف أولاً.",
			["BzWiping"] = "جارٍ مسح القرص {0} ({1})...",
			["MbSurfaceTitle"] = "DriveForge — اختبار السطح",
			["Mb008"] = "القرص المحدد مُعلَّم كقرص نظام/إقلاع. لن يقوم DriveForge بتهيئته.",
			["BzCapacity"] = "جارٍ اختبار السعة الفعلية لـ {0}:...",
			["Mb025"] = "يبدو هذا كصورة ISO خاصة بـ Windows / WinPE.\n\nصور Windows ISO ليست \"isohybrid\"، لذا فإن كتابة إحداها كصورة خام عادةً لا تُقلع. للحصول على USB إقلاعي صحيح لـ Windows، استخدم مهمة \"[[SbCreateT]]\" بدلاً من ذلك.\n\nكتابتها كصورة خام على أي حال؟",
			["Mb003"] = "حدد ملف Windows ISO / WIM / ESD أولاً.",
			["BzVerify"] = "جارٍ التحقق من القرص {0}...",
			["MbTestBootTitle"] = "DriveForge — اختبار الإقلاع",
			["MbBackupCreated"] = "تم إنشاء صورة النسخة الاحتياطية:\n\n{0}  ({1})\n\nلاستعادتها لاحقاً: اختر \"[[SbRestoreT]]\"، واختر ملف .wim هذا، ثم حدد محرك الأقراص الهدف.",
			["MbFormatConfirm"] = "تهيئة (محو) محرك الأقراص هذا؟\n\n    القرص {0} — {1} — {2}\n\nيحتوي هذا القرص حالياً على:\n{3}\n\n⚠ سيُمحى كل ما سبق نهائياً.",
			["MbSchedDaily"] = "كل يوم",
			["MbBackupNoSpace"] = "لا توجد مساحة حرة كافية في المكان الذي تحفظ فيه الصورة.\n\nالمساحة المقدَّرة المطلوبة: ~{0}\nالمساحة الحرة في الوجهة: {1}",
			["MbWriteIsoTitle"] = "DriveForge — كتابة ISO",
			["Mb014"] = "يجب أن تتكوّن كلمات مرور BitLocker من 8 أحرف على الأقل (أو اترك كلتيهما فارغتين لاستخدام مفتاح الاسترداد فقط).",
			["BzShred"] = "جارٍ تمزيق {0} من الملفات...",
			["Mb011"] = "أعد تشغيل DriveForge كمسؤول لإنشاء صورة نسخة احتياطية.",
			["Mb012"] = "أدخل اسم حساب صالحاً (بدون أحرف خاصة).",
			["Mb039"] = "اختر محرك أقراص لاختباره أولاً.",
			["Mb036"] = "أعد تشغيل DriveForge كمسؤول لإنشاء USB متعدد الإقلاع.",
			["Mb006"] = "إيقاف العملية الحالية؟ قد يكون USB غير مكتمل وقد يحتاج إلى التهيئة مرة أخرى.",
			["Mb033"] = "اختر توزيعة من القائمة أولاً.",
			["MbFormatTitle"] = "DriveForge — تهيئة محرك الأقراص",
			["Mb004"] = "لا تزال هناك عملية قيد التشغيل. قد يؤدي إغلاق التطبيق إلى ترك USB غير مكتمل. هل أنت متأكد من أنك تريد الإغلاق؟",
			["Mb009"] = "حدد صورة المصدر أولاً.",
			["MbWipeFreeTitle"] = "DriveForge — مسح المساحة الحرة",
